    WHERE
      CASE
        WHEN time_filter = 'weekly' THEN up.updated_at >= (now() - interval '7 days')
        WHEN time_filter = 'monthly' THEN up.updated_at >= (now() - interval '30 days')
        ELSE true
      END
    ORDER BY up.points DESC
