-- Source migration: 20260402020726_update_rpc_learning_path
-- Source ledger: repository
-- ============================================================================
CREATE OR REPLACE FUNCTION public.get_learning_path_data()
RETURNS json
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_user_id UUID;
    v_result JSON;
    v_path_record RECORD;
    v_activities JSON;
    v_module_averages JSON;
    v_module_trends JSON;
    v_skill_proficiencies JSON;
    v_sessions JSON;
    v_total_tests INTEGER;
BEGIN
    -- Resolve user from auth context
    SELECT id INTO v_user_id FROM public.users WHERE auth_id = auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated or user not found';
    END IF;

    -- 1. Get latest learning path
    SELECT id, path_data, activities_completed, created_at
    INTO v_path_record
    FROM learning_paths
    WHERE user_id = v_user_id
    ORDER BY created_at DESC
    LIMIT 1;
    
    -- 2. Get activities for the learning path (if exists)
    IF v_path_record.id IS NOT NULL THEN
        SELECT COALESCE(json_agg(
            json_build_object(
                'id', id,
                'activity_key', activity_key,
                'scheduled_day', scheduled_day,
                'is_completed', is_completed,
                'completed_at', completed_at,
                'outcome_score', outcome_score,
                'outcome_data', outcome_data,
                'title', title,
                'module', module,
                'estimated_minutes', estimated_minutes,
                'priority', priority,
                'activity_type', activity_type,
                'skill_targets', skill_targets
            )
        ), '[]'::json)
        INTO v_activities
        FROM learning_path_activities
        WHERE learning_path_id = v_path_record.id;
    ELSE
        v_activities := '[]'::json;
    END IF;
    
    -- 3. Get recent test sessions and calculate module averages/trends
    WITH recent_sessions AS (
        SELECT 
            ts.id,
            ts.test_type,
            ts.score,
            ts.completed_at,
            ROW_NUMBER() OVER (PARTITION BY ts.test_type ORDER BY ts.completed_at DESC) as rn
        FROM test_sessions ts
        WHERE ts.user_id = v_user_id
          AND ts.is_completed = true
          AND ts.score IS NOT NULL
        ORDER BY ts.completed_at DESC
        LIMIT 40
    ),
    module_stats AS (
        SELECT 
            test_type,
            AVG(score) as avg_score,
            MAX(CASE WHEN rn = 1 THEN score END) as latest_score,
            MAX(CASE WHEN rn = 2 THEN score END) as prev_score
        FROM recent_sessions
        GROUP BY test_type
    )
    SELECT 
        COALESCE(json_object_agg(test_type, ROUND(avg_score::numeric, 2)), '{}'::json),
        COALESCE(json_object_agg(
            test_type,
            CASE 
                WHEN latest_score > prev_score THEN 'up'
                WHEN latest_score < prev_score THEN 'down'
                ELSE 'stable'
            END
        ), '{}'::json)
    INTO v_module_averages, v_module_trends
    FROM module_stats
    WHERE avg_score IS NOT NULL;
    
    -- Get total test count
    SELECT COUNT(*)
    INTO v_total_tests
    FROM test_sessions
    WHERE user_id = v_user_id AND is_completed = true;
    
    -- Get sessions for skill trend calculation (last 40)
    SELECT COALESCE(json_agg(
        json_build_object(
            'id', s.id,
            'test_type', s.test_type,
            'score', s.score,
            'completed_at', s.completed_at,
            'content_data', s.content_data
        )
    ), '[]'::json)
    INTO v_sessions
    FROM (
        SELECT ts.id, ts.test_type, ts.score, ts.completed_at, ts.content_data
        FROM test_sessions ts
        WHERE ts.user_id = v_user_id AND ts.is_completed = true
        ORDER BY ts.completed_at DESC
        LIMIT 40
    ) s;
    
    -- 4. Get skill proficiencies (top 100 by lowest mastery)
    SELECT COALESCE(json_agg(
        json_build_object(
            'skill_code', sp.skill_code,
            'module', sp.module,
            'mastery_probability', sp.mastery_probability,
            'confidence_level', sp.confidence_level,
            'practice_count', sp.practice_count,
            'correct_count', sp.correct_count,
            'last_practiced_at', sp.last_practiced_at,
            'next_review_at', sp.next_review_at
        )
    ), '[]'::json)
    INTO v_skill_proficiencies
    FROM (
        SELECT *
        FROM public.skill_proficiency
        WHERE user_id = v_user_id
        ORDER BY mastery_probability ASC
        LIMIT 100
    ) sp;
    
    -- Build final result
    v_result := json_build_object(
        'learningPath', CASE 
            WHEN v_path_record.id IS NOT NULL THEN
                json_build_object(
                    'id', v_path_record.id,
                    'path_data', v_path_record.path_data,
                    'activities_completed', v_path_record.activities_completed,
                    'created_at', v_path_record.created_at
                )
            ELSE NULL
        END,
        'activities', v_activities,
        'stats', json_build_object(
            'moduleAverages', COALESCE(v_module_averages, '{}'::json),
            'moduleTrends', COALESCE(v_module_trends, '{}'::json),
            'totalTests', COALESCE(v_total_tests, 0),
            'sessions', v_sessions
        ),
        'skillProficiencies', v_skill_proficiencies
    );
    
    RETURN v_result;
END;
$$;

-- ============================================================================
-- Source migration: 20260402020905_backfill_writing_speaking_skills
-- Source ledger: repository
-- ============================================================================
-- ============================================================
-- Backfill writing and speaking test skills
-- ============================================================
-- This migration simulates a re-completion of legacy writing
-- and speaking tests to trigger the newly updated
-- update_skill_proficiency_from_test() logic and populate the
-- missing criteria-based skill proficiencies.

DO $$
DECLARE
  v_session_id UUID;
BEGIN
  -- We order by completed_at ASC so that early tests are
  -- factored into the learning curve first, preserving
  -- the chronological mastery progression.
  FOR v_session_id IN (
      SELECT id 
      FROM public.test_sessions 
      WHERE is_completed = true 
        AND test_type IN ('writing', 'speaking') 
      ORDER BY completed_at ASC
  ) LOOP
     -- Temporarily toggling is_completed fires the trigger securely
     -- because the trigger condition checks if OLD.is_completed was false
     UPDATE public.test_sessions SET is_completed = false WHERE id = v_session_id;
     UPDATE public.test_sessions SET is_completed = true WHERE id = v_session_id;
  END LOOP;
END;
$$;

-- ============================================================================
-- Source migration: 20260402034000_user_profile_auto_update
-- Source ledger: repository
-- ============================================================================
-- ============================================================
-- Auto-Update User Profile After Test Completion
-- ============================================================
-- Creates a trigger that fires after a test_session is completed.
-- Updates the user's profile with:
--   - current_estimated_band (average of latest score per module)
--   - total_study_time (sum of all completed session durations)
--   - strengths (modules with avg >= 7.0)
--   - weaknesses (modules with avg < 6.0)
--   - current_streak / longest_streak (consecutive days with tests)
-- ============================================================

CREATE OR REPLACE FUNCTION "public"."update_user_profile_after_test"()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_user_id         UUID;
  v_module_scores   RECORD;
  v_estimated_band  FLOAT;
  v_total_minutes   INT;
  v_strengths       TEXT[];
  v_weaknesses      TEXT[];
  v_module_count    INT := 0;
  v_score_sum       FLOAT := 0;
  v_streak          INT;
  v_longest_streak  INT;
  v_last_study      DATE;
  v_today           DATE := CURRENT_DATE;
BEGIN
  -- Only run when a test transitions to completed
  IF NOT (NEW.is_completed = true AND (OLD IS NULL OR OLD.is_completed = false)) THEN
    RETURN NEW;
  END IF;

  v_user_id := NEW.user_id;
  v_strengths := ARRAY[]::TEXT[];
  v_weaknesses := ARRAY[]::TEXT[];

  -- Calculate latest average score per module
  FOR v_module_scores IN
    SELECT test_type,
           AVG(score) as avg_score,
           MAX(score) as best_score
    FROM (
      SELECT test_type, score,
             ROW_NUMBER() OVER (PARTITION BY test_type ORDER BY completed_at DESC) as rn
      FROM test_sessions
      WHERE user_id = v_user_id AND is_completed = true AND score > 0
    ) recent
    WHERE rn <= 5  -- Use last 5 tests per module for average
    GROUP BY test_type
  LOOP
    v_module_count := v_module_count + 1;
    v_score_sum := v_score_sum + v_module_scores.avg_score;

    IF v_module_scores.avg_score >= 7.0 THEN
      v_strengths := array_append(v_strengths, v_module_scores.test_type);
    ELSIF v_module_scores.avg_score < 6.0 THEN
      v_weaknesses := array_append(v_weaknesses, v_module_scores.test_type);
    END IF;
  END LOOP;

  -- Calculate estimated band (average of module averages)
  IF v_module_count > 0 THEN
    v_estimated_band := ROUND((v_score_sum / v_module_count * 2)::NUMERIC) / 2.0;
  ELSE
    v_estimated_band := NULL;
  END IF;

  -- Calculate total study time in minutes
  SELECT COALESCE(SUM(
    CASE
      WHEN duration_minutes > 0 THEN duration_minutes
      WHEN completed_at IS NOT NULL AND created_at IS NOT NULL THEN
        LEAST(EXTRACT(EPOCH FROM (completed_at - created_at)) / 60, 240)::INT
      ELSE 20  -- Default estimate
    END
  ), 0)
  INTO v_total_minutes
  FROM test_sessions
  WHERE user_id = v_user_id AND is_completed = true;

  -- Calculate streak
  SELECT current_streak, longest_streak, last_study_date
  INTO v_streak, v_longest_streak, v_last_study
  FROM users WHERE id = v_user_id;

  v_streak := COALESCE(v_streak, 0);
  v_longest_streak := COALESCE(v_longest_streak, 0);

  IF v_last_study IS NULL OR v_last_study < v_today - 1 THEN
    -- Streak broken or first time
    v_streak := 1;
  ELSIF v_last_study = v_today - 1 THEN
    -- Consecutive day
    v_streak := v_streak + 1;
  END IF;
  -- If v_last_study = v_today, streak stays the same (already counted today)

  IF v_streak > v_longest_streak THEN
    v_longest_streak := v_streak;
  END IF;

  -- Update user profile
  UPDATE users SET
    current_estimated_band = v_estimated_band,
    total_study_time = v_total_minutes,
    strengths = CASE WHEN array_length(v_strengths, 1) > 0 THEN v_strengths ELSE strengths END,
    weaknesses = CASE WHEN array_length(v_weaknesses, 1) > 0 THEN v_weaknesses ELSE weaknesses END,
    current_streak = v_streak,
    longest_streak = v_longest_streak,
    last_study_date = v_today,
    updated_at = NOW()
  WHERE id = v_user_id;

  RETURN NEW;
END;
$$;

