    VALUES (v_referrer_id, p_new_user_id);

    UPDATE public.users SET referred_by = v_referrer_id WHERE id = p_new_user_id;

    RETURN jsonb_build_object('success', true, 'referrer_id', v_referrer_id);
END;
$$;

