      )
  )
  RETURNING id INTO v_reservation_id;

  RETURN QUERY SELECT
    v_reservation_id,
    true,
    GREATEST(COALESCE(v_quota.daily_remaining, 1) - 1, 0),
    GREATEST(COALESCE(v_quota.monthly_remaining, 1) - 1, 0),
    COALESCE(v_quota.daily_used, 0) + 1,
    COALESCE(v_quota.monthly_used, 0) + 1,
    false;
END;
$$;

