-- Superseded by 20260730213212_admin_overview_rpc_v2.sql, which replaces the
-- same function. This file exists so the local migration history matches the
-- versions recorded on the remote project.
SELECT 1;

-- ============================================================================
-- Source migration: 20260730213212_admin_overview_rpc_v2
-- Source ledger: repository
-- ============================================================================
-- Admin overview snapshot.
--
-- Replaces the old client-side approach where AdminOverview pulled 10,000 users
-- and 10,000 test_sessions into the browser and aggregated there. Everything is
-- computed in Postgres in one round trip.
--
-- v2 additions over the first cut: weekly cohort retention, repeat/power-user
-- depth, unit economics (AI cost per completed test and per paying user),
-- mock-vs-practice split and hour-of-day volume. The daily trend no longer runs
-- correlated subqueries per generated day — each source table is scanned once
-- and joined onto the date spine. Supporting indexes already exist
-- (idx_users_created_at, idx_users_last_active, idx_test_sessions_created_at).

CREATE OR REPLACE FUNCTION public.get_admin_overview(p_days integer DEFAULT 7)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
    v_days      integer;
    v_since     timestamptz;
    v_prev      timestamptz;

    v_signups bigint; v_signups_prev bigint;
    v_dau bigint; v_wau bigint; v_mau bigint; v_active_prev bigint;
    v_total_users bigint;
    v_pro bigint; v_premium bigint;
    v_rev_usd numeric; v_rev_bdt numeric; v_rev_usd_prev numeric;
    v_ai_cost numeric; v_ai_cost_prev numeric; v_ai_priced bigint; v_ai_total bigint;

    v_f_signed bigint; v_f_onboarded bigint; v_f_started bigint;
    v_f_completed bigint; v_f_paid bigint;

    v_pending_pay bigint; v_pending_oldest numeric;
    v_stuck bigint; v_cancelling bigint; v_expiring bigint; v_eval_failed bigint;

    v_started_users bigint; v_repeat_users bigint; v_power_users bigint;
    v_completed_tests bigint;
    v_mock bigint; v_practice bigint;

    v_trend jsonb; v_modules jsonb; v_recent jsonb; v_actions jsonb := '[]'::jsonb;
    v_retention jsonb; v_hours jsonb;
BEGIN
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Access denied';
    END IF;

    v_days  := GREATEST(COALESCE(p_days, 7), 1);
    v_since := now() - make_interval(days => v_days);
    v_prev  := now() - make_interval(days => v_days * 2);

    -- Users: one pass for every user-derived counter.
    SELECT
        count(*),
        count(*) FILTER (WHERE created_at >= v_since),
        count(*) FILTER (WHERE created_at >= v_prev AND created_at < v_since),
        count(*) FILTER (WHERE last_active > now() - interval '1 day'),
        count(*) FILTER (WHERE last_active > now() - interval '7 days'),
        count(*) FILTER (WHERE last_active > now() - interval '30 days'),
        count(*) FILTER (WHERE last_active >= v_prev AND last_active < v_since),
        count(*) FILTER (WHERE subscription_tier = 'pro'),
        count(*) FILTER (WHERE subscription_tier = 'premium'),
        count(*) FILTER (WHERE onboarding_completed),
        count(*) FILTER (WHERE cancel_at_period_end IS TRUE
                           AND subscription_tier IN ('pro','premium')),
        count(*) FILTER (WHERE subscription_tier IN ('pro','premium')
                           AND subscription_end_date IS NOT NULL
                           AND subscription_end_date BETWEEN now() AND now() + interval '7 days')
    INTO v_total_users, v_signups, v_signups_prev, v_dau, v_wau, v_mau,
         v_active_prev, v_pro, v_premium, v_f_onboarded, v_cancelling, v_expiring
    FROM public.users;

    v_f_signed := v_total_users;
    v_f_paid   := v_pro + v_premium;

    -- Sessions: one pass.
    SELECT
        count(DISTINCT user_id),
        count(DISTINCT user_id) FILTER (WHERE is_completed),
        count(*) FILTER (WHERE is_completed),
        count(*) FILTER (WHERE test_mode = 'mock'),
        count(*) FILTER (WHERE test_mode = 'practice'),
        count(*) FILTER (WHERE evaluation_status = 'failed')
    INTO v_f_started, v_f_completed, v_completed_tests, v_mock, v_practice, v_eval_failed
    FROM public.test_sessions;

    SELECT
        count(*),
        count(*) FILTER (WHERE n >= 2),
        count(*) FILTER (WHERE n >= 5)
    INTO v_started_users, v_repeat_users, v_power_users
    FROM (SELECT user_id, count(*) AS n FROM public.test_sessions GROUP BY user_id) s;

    -- Revenue: billing_history plus payment_requests, deduped on transaction_id.
    WITH paid AS (
        SELECT bh.amount, bh.payment_method, bh.created_at
        FROM public.billing_history bh WHERE bh.status = 'paid'
        UNION ALL
        SELECT pr.amount, pr.payment_method, pr.created_at
        FROM public.payment_requests pr
        WHERE pr.status = 'approved'
          AND NOT EXISTS (
              SELECT 1 FROM public.billing_history b
              WHERE b.status = 'paid' AND b.transaction_id IS NOT NULL
                AND b.transaction_id = pr.transaction_id)
    )
    SELECT
        COALESCE(sum(amount) FILTER (WHERE lower(payment_method) = 'stripe' AND created_at >= v_since), 0),
        COALESCE(sum(amount) FILTER (WHERE lower(payment_method) <> 'stripe' AND created_at >= v_since), 0),
        COALESCE(sum(amount) FILTER (WHERE lower(payment_method) = 'stripe'
                                       AND created_at >= v_prev AND created_at < v_since), 0)
    INTO v_rev_usd, v_rev_bdt, v_rev_usd_prev
    FROM paid;

    -- AI spend: only rows carrying a cost estimate contribute.
    SELECT
        COALESCE(sum((request_metadata->>'estimatedProviderCostUsd')::numeric)
                 FILTER (WHERE jsonb_typeof(request_metadata->'estimatedProviderCostUsd') = 'number'
                           AND created_at >= v_since), 0),
        COALESCE(sum((request_metadata->>'estimatedProviderCostUsd')::numeric)
                 FILTER (WHERE jsonb_typeof(request_metadata->'estimatedProviderCostUsd') = 'number'
                           AND created_at >= v_prev AND created_at < v_since), 0),
        count(*) FILTER (WHERE jsonb_typeof(request_metadata->'estimatedProviderCostUsd') = 'number'
                           AND created_at >= v_since),
        count(*) FILTER (WHERE created_at >= v_since)
    INTO v_ai_cost, v_ai_cost_prev, v_ai_priced, v_ai_total
    FROM public.ai_api_usage;

    -- Action queue.
    SELECT
        count(*) FILTER (WHERE status = 'pending'),
        COALESCE(extract(epoch FROM (now() - min(created_at) FILTER (WHERE status = 'pending'))) / 3600, 0)
    INTO v_pending_pay, v_pending_oldest
    FROM public.payment_requests;

    SELECT count(*) INTO v_stuck
    FROM public.ai_api_usage
    WHERE request_metadata->>'reservationStatus' = 'reserved'
      AND created_at < now() - interval '1 hour'
      AND created_at >= now() - interval '30 days';

    IF v_pending_pay > 0 THEN
        v_actions := v_actions || jsonb_build_object(
            'key','pending_payments','label','Payment requests awaiting approval',
            'count',v_pending_pay,'severity','high',
            'detail','Oldest waiting ' || round(v_pending_oldest) || 'h - these users have paid but are still on the free tier.',
            'tab','payments');
    END IF;
    IF v_stuck > 0 THEN
        v_actions := v_actions || jsonb_build_object(
            'key','stuck_reservations','label','Stuck AI reservations',
            'count',v_stuck,'severity',CASE WHEN v_stuck >= 10 THEN 'high' ELSE 'medium' END,
            'detail','Quota was consumed but the request never completed.','tab','ai-usage');
    END IF;
    IF v_eval_failed > 0 THEN
        v_actions := v_actions || jsonb_build_object(
            'key','eval_failed','label','Test evaluations failed',
            'count',v_eval_failed,'severity','high',
            'detail','Learners finished a test but never received a score.','tab','ai-usage');
    END IF;
    IF v_cancelling > 0 THEN
        v_actions := v_actions || jsonb_build_object(
            'key','cancelling','label','Subscriptions set to cancel',
            'count',v_cancelling,'severity','medium',
            'detail','Will not renew at the end of the current period.','tab','users');
    END IF;
    IF v_expiring > 0 THEN
        v_actions := v_actions || jsonb_build_object(
            'key','expiring','label','Subscriptions expiring within 7 days',
            'count',v_expiring,'severity','low','detail','Renewal or outreach window.','tab','users');
    END IF;

    -- Daily trend: grouped passes joined onto a date spine (no per-day subqueries).
    WITH spine AS (
        SELECT generate_series(date_trunc('day', v_since), date_trunc('day', now()), interval '1 day') AS day
    ),
    su AS (
        SELECT date_trunc('day', created_at) AS day, count(*) AS n
        FROM public.users WHERE created_at >= date_trunc('day', v_since) GROUP BY 1
    ),
    ac AS (
        SELECT date_trunc('day', last_active) AS day, count(*) AS n
        FROM public.users WHERE last_active >= date_trunc('day', v_since) GROUP BY 1
    ),
    se AS (
        SELECT date_trunc('day', created_at) AS day, count(*) AS n
        FROM public.test_sessions WHERE created_at >= date_trunc('day', v_since) GROUP BY 1
    )
    SELECT jsonb_agg(jsonb_build_object(
               'date', to_char(spine.day, 'Mon DD'),
               'signups', COALESCE(su.n, 0),
               'active',  COALESCE(ac.n, 0),
               'sessions',COALESCE(se.n, 0)) ORDER BY spine.day)
    INTO v_trend
    FROM spine
    LEFT JOIN su ON su.day = spine.day
    LEFT JOIN ac ON ac.day = spine.day
    LEFT JOIN se ON se.day = spine.day;

    -- Weekly cohort retention over the last 6 signup weeks.
    WITH cohort AS (
        SELECT id, date_trunc('week', created_at) AS wk
        FROM public.users
        WHERE created_at >= date_trunc('week', now() - interval '5 weeks')
    ),
    act AS (
        SELECT DISTINCT user_id, date_trunc('week', created_at) AS wk
        FROM public.test_sessions
        WHERE created_at >= date_trunc('week', now() - interval '5 weeks')
    ),
    joined AS (
        SELECT c.wk AS cohort_wk,
               c.id,
               (extract(epoch FROM (a.wk - c.wk)) / 604800)::int AS week_offset
        FROM cohort c
        LEFT JOIN act a ON a.user_id = c.id AND a.wk >= c.wk
    )
    SELECT jsonb_agg(jsonb_build_object(
               'cohort', to_char(cohort_wk, 'Mon DD'),
               'size',   size,
               'w0',     w0, 'w1', w1, 'w2', w2, 'w3', w3) ORDER BY cohort_wk)
    INTO v_retention
    FROM (
        SELECT cohort_wk,
               count(DISTINCT id) AS size,
               count(DISTINCT id) FILTER (WHERE week_offset = 0) AS w0,
               count(DISTINCT id) FILTER (WHERE week_offset = 1) AS w1,
               count(DISTINCT id) FILTER (WHERE week_offset = 2) AS w2,
               count(DISTINCT id) FILTER (WHERE week_offset = 3) AS w3
        FROM joined GROUP BY cohort_wk
    ) r;

    -- Session volume by hour of day (UTC).
    WITH hrs AS (SELECT generate_series(0, 23) AS h),
    s AS (
        SELECT extract(hour FROM created_at)::int AS h, count(*) AS n
        FROM public.test_sessions
        WHERE created_at >= now() - interval '30 days' GROUP BY 1
    )
    SELECT jsonb_agg(jsonb_build_object('hour', hrs.h, 'sessions', COALESCE(s.n, 0)) ORDER BY hrs.h)
    INTO v_hours
    FROM hrs LEFT JOIN s ON s.h = hrs.h;

    SELECT jsonb_agg(t ORDER BY t.sessions DESC)
    INTO v_modules
    FROM (
        SELECT initcap(test_type) AS module,
               count(DISTINCT user_id) AS users,
               count(*) AS sessions,
               COALESCE(round(100.0 * count(*) FILTER (WHERE is_completed) / NULLIF(count(*), 0), 1), 0) AS completion
        FROM public.test_sessions WHERE test_type IS NOT NULL GROUP BY test_type
    ) t;

    SELECT jsonb_agg(t)
    INTO v_recent
    FROM (
        SELECT id, full_name, email, created_at, subscription_tier, onboarding_completed
        FROM public.users ORDER BY created_at DESC LIMIT 8
    ) t;

    RETURN jsonb_build_object(
        'generatedAt', now(),
        'windowDays',  v_days,
        'kpis', jsonb_build_object(
            'signups', jsonb_build_object('value', v_signups, 'prev', v_signups_prev),
            'active',  jsonb_build_object('dau', v_dau, 'wau', v_wau, 'mau', v_mau, 'prev', v_active_prev,
                          'stickiness', CASE WHEN v_mau > 0 THEN round(100.0 * v_dau / v_mau, 1) ELSE 0 END),
            'paying',  jsonb_build_object('pro', v_pro, 'premium', v_premium, 'total', v_f_paid,
                          'conversion', CASE WHEN v_total_users > 0
                                          THEN round(100.0 * v_f_paid / v_total_users, 1) ELSE 0 END),
            'revenue', jsonb_build_object('usd', v_rev_usd, 'bdt', v_rev_bdt, 'prevUsd', v_rev_usd_prev),
            'aiCost',  jsonb_build_object('usd', round(v_ai_cost, 4), 'prevUsd', round(v_ai_cost_prev, 4),
                          'pricedCalls', v_ai_priced, 'totalCalls', v_ai_total,
                          'perActiveUser', CASE WHEN v_wau > 0 THEN round(v_ai_cost / v_wau, 4) ELSE 0 END)
        ),
        'economics', jsonb_build_object(
            'costPerCompletedTest', CASE WHEN v_completed_tests > 0
                                      THEN round(v_ai_cost / v_completed_tests, 4) ELSE 0 END,
            'costPerPayingUser',    CASE WHEN v_f_paid > 0
                                      THEN round(v_ai_cost / v_f_paid, 4) ELSE 0 END,
            'completedTests',       v_completed_tests,
            'costCoverage',         CASE WHEN v_ai_total > 0
                                      THEN round(100.0 * v_ai_priced / v_ai_total, 1) ELSE 0 END
        ),
        'engagement', jsonb_build_object(
            'startedUsers', v_started_users,
            'repeatUsers',  v_repeat_users,
            'powerUsers',   v_power_users,
            'repeatRate',   CASE WHEN v_started_users > 0
                              THEN round(100.0 * v_repeat_users / v_started_users, 1) ELSE 0 END,
            'mockSessions', v_mock,
            'practiceSessions', v_practice
        ),
        'funnel', jsonb_build_array(
            jsonb_build_object('key','signed_up','label','Signed up','users',v_f_signed),
            jsonb_build_object('key','onboarded','label','Finished onboarding','users',v_f_onboarded),
            jsonb_build_object('key','started','label','Started a test','users',v_f_started),
            jsonb_build_object('key','completed','label','Completed a test','users',v_f_completed),
            jsonb_build_object('key','paid','label','Subscribed','users',v_f_paid)
        ),
        'actions',       v_actions,
        'trend',         COALESCE(v_trend, '[]'::jsonb),
        'retention',     COALESCE(v_retention, '[]'::jsonb),
        'hourly',        COALESCE(v_hours, '[]'::jsonb),
        'modules',       COALESCE(v_modules, '[]'::jsonb),
        'recentSignups', COALESCE(v_recent, '[]'::jsonb),
        'totals',        jsonb_build_object('users', v_total_users)
    );
END;
$function$;

REVOKE ALL ON FUNCTION public.get_admin_overview(integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_admin_overview(integer) FROM anon;
GRANT EXECUTE ON FUNCTION public.get_admin_overview(integer) TO authenticated;

COMMENT ON FUNCTION public.get_admin_overview(integer) IS
'Admin landing-page snapshot: KPIs with prior-period deltas, activation funnel, action queue, cohort retention, unit economics, daily trend and module engagement in one call.';

-- ============================================================================
-- Source migration: 20260730214538_admin_resolve_stuck_reservations
-- Source ledger: repository
-- ============================================================================
-- Repair action for stuck AI quota reservations.
--
-- reserve_ai_api_usage() inserts an ai_api_usage row up front, and quota is
-- counted by get_user_daily_usage() as "every non-cached row today" — it does
-- not look at reservationStatus. So a reservation that never finalised has
-- permanently consumed the learner's quota for a request that never ran.
-- Flagging it 'failed' would not give the quota back; only removing the
-- phantom row does. This deletes reservations that are old enough that they can
-- no longer be legitimately finalised.
CREATE OR REPLACE FUNCTION public.resolve_stuck_ai_reservations(
    p_older_than_minutes integer DEFAULT 60,
    p_dry_run boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
    v_cutoff   timestamptz;
    v_affected bigint;
    v_users    bigint;
    v_deleted  bigint := 0;
BEGIN
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Access denied';
    END IF;

    -- Never let the caller reach back into in-flight requests.
    v_cutoff := now() - make_interval(mins => GREATEST(COALESCE(p_older_than_minutes, 60), 15));

    SELECT count(*), count(DISTINCT user_id)
    INTO v_affected, v_users
    FROM public.ai_api_usage
    WHERE request_metadata->>'reservationStatus' = 'reserved'
      AND created_at < v_cutoff;

    IF NOT COALESCE(p_dry_run, true) THEN
        DELETE FROM public.ai_api_usage
        WHERE request_metadata->>'reservationStatus' = 'reserved'
          AND created_at < v_cutoff;
        GET DIAGNOSTICS v_deleted = ROW_COUNT;

        INSERT INTO public.system_health_logs (level, component, message, metadata)
        VALUES ('info', 'AdminRepair',
                'Released ' || v_deleted || ' stuck AI quota reservation(s)',
                jsonb_build_object('cutoff', v_cutoff, 'usersAffected', v_users));
    END IF;

    RETURN jsonb_build_object(
        'dryRun',        COALESCE(p_dry_run, true),
        'cutoff',        v_cutoff,
        'matched',       v_affected,
        'usersAffected', v_users,
        'deleted',       v_deleted
    );
END;
$function$;

REVOKE ALL ON FUNCTION public.resolve_stuck_ai_reservations(integer, boolean) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.resolve_stuck_ai_reservations(integer, boolean) FROM anon;
GRANT EXECUTE ON FUNCTION public.resolve_stuck_ai_reservations(integer, boolean) TO authenticated;

COMMENT ON FUNCTION public.resolve_stuck_ai_reservations(integer, boolean) IS
'Admin-only. Releases AI quota consumed by reservations that never finalised. Defaults to a dry run; pass p_dry_run => false to actually delete.';

-- ============================================================================
-- Source migration: 20260801000000_exclude_abandoned_sessions_from_dashboard_stats
-- Source ledger: repository
-- ============================================================================
-- ============================================================================
-- Exclude walk-away sessions (opened, abandoned within minutes, scored 0) from
-- dashboard band averages and recent-session lists.
--
-- Mirrors the same fix already applied client-side in
-- src/features/analytics/hooks/analyticsCalculations.js (isAbandonedSession):
-- a session only counts as "abandoned" when ALL of the following hold —
--   - score = 0 (never touches a genuine low score)
--   - no correct answers recorded (content_data.correctAnswers/correct)
--   - a known duration under 5 minutes
-- Sessions with unknown duration are left alone rather than guessed at.
-- ============================================================================

-- 1. Best-known duration for a session, mirroring getKnownDurationSeconds().
CREATE OR REPLACE FUNCTION public.get_session_duration_seconds(
    p_test_type TEXT,
    p_actual_duration_seconds INTEGER,
    p_content_data JSONB
)
RETURNS INTEGER
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    v_metric NUMERIC;
    v_benchmark_minutes INTEGER;
    v_remaining NUMERIC;
    v_elapsed NUMERIC;
BEGIN
    IF p_actual_duration_seconds IS NOT NULL
       AND p_actual_duration_seconds > 0
       AND p_actual_duration_seconds <= 14400 THEN
        RETURN p_actual_duration_seconds;
    END IF;

    v_metric := NULLIF(p_content_data #>> '{timeMetrics,totalTimeSpent}', '')::NUMERIC;
    IF v_metric IS NOT NULL AND v_metric > 0 AND v_metric <= 14400 THEN
        RETURN v_metric::INTEGER;
    END IF;

    v_benchmark_minutes := CASE LOWER(COALESCE(p_test_type, ''))
        WHEN 'reading' THEN 60
        WHEN 'writing' THEN 60
        WHEN 'listening' THEN 40
        WHEN 'speaking' THEN 15
        ELSE NULL
    END;
    v_remaining := NULLIF(p_content_data ->> 'time_remaining', '')::NUMERIC;
    IF v_benchmark_minutes IS NOT NULL AND v_remaining IS NOT NULL AND v_remaining >= 0 THEN
        v_elapsed := v_benchmark_minutes * 60 - v_remaining;
        IF v_elapsed > 0 AND v_elapsed <= 14400 THEN
            RETURN v_elapsed::INTEGER;
        END IF;
    END IF;

    RETURN NULL;
EXCEPTION WHEN OTHERS THEN
    -- A malformed content_data value should never break an aggregate query.
    RETURN NULL;
END;
$$;

-- 2. A test the learner opened and walked away from, not a test they sat and
-- failed. See isAbandonedSession() in analyticsCalculations.js for the
-- rationale — this is the same predicate.
CREATE OR REPLACE FUNCTION public.is_abandoned_test_session(
    p_test_type TEXT,
    p_score NUMERIC,
    p_actual_duration_seconds INTEGER,
    p_content_data JSONB
)
RETURNS BOOLEAN
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
    v_correct NUMERIC;
    v_duration INTEGER;
BEGIN
    IF p_score IS NULL OR p_score <> 0 THEN
        RETURN FALSE;
    END IF;

    v_correct := NULLIF(COALESCE(p_content_data ->> 'correctAnswers', p_content_data ->> 'correct'), '')::NUMERIC;
    IF v_correct IS NOT NULL AND v_correct > 0 THEN
        RETURN FALSE;
    END IF;

    v_duration := public.get_session_duration_seconds(p_test_type, p_actual_duration_seconds, p_content_data);
    IF v_duration IS NULL THEN
        RETURN FALSE;
    END IF;

    RETURN v_duration < 300;
EXCEPTION WHEN OTHERS THEN
    RETURN FALSE;
END;
$$;

-- 3. get_dashboard_stats — averages now exclude abandoned sessions. totalTests
-- stays a raw activity count (unchanged meaning); two new keys report how many
-- of the scored sessions were excluded, so the UI can be transparent about it.
CREATE OR REPLACE FUNCTION public.get_dashboard_stats()
RETURNS json
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_user_id UUID;
    result JSON;
    v_total_tests INTEGER;
    v_avg_score NUMERIC;
    v_measured_tests INTEGER;
    v_abandoned_tests INTEGER;
    v_today_minutes INTEGER;
    v_today_tests INTEGER;
    v_streak INTEGER;
    v_module_averages JSON;
    v_weekly_data JSON;
    v_daily_activity JSON;
BEGIN
    -- Resolve user from auth context
    SELECT id INTO v_user_id FROM public.users WHERE auth_id = auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated or user not found';
    END IF;

    -- Get basic stats from test sessions
    SELECT
        COUNT(*),
        COUNT(*) FILTER (WHERE NOT public.is_abandoned_test_session(test_type, score, actual_duration_seconds, content_data)),
        COUNT(*) FILTER (WHERE public.is_abandoned_test_session(test_type, score, actual_duration_seconds, content_data)),
        COALESCE(AVG(score) FILTER (WHERE NOT public.is_abandoned_test_session(test_type, score, actual_duration_seconds, content_data)), 0)
    INTO v_total_tests, v_measured_tests, v_abandoned_tests, v_avg_score
    FROM test_sessions
    WHERE user_id = v_user_id
      AND is_completed = true
      AND score IS NOT NULL;

    -- Get today's stats (timestamp range instead of ::date cast)
    SELECT
        COALESCE(SUM(duration), 0)::INTEGER,
        COUNT(*)::INTEGER
    INTO v_today_minutes, v_today_tests
    FROM (
        SELECT duration_minutes as duration FROM test_sessions
        WHERE user_id = v_user_id AND is_completed = true
          AND completed_at >= CURRENT_DATE AND completed_at < CURRENT_DATE + INTERVAL '1 day'
        UNION ALL
        SELECT estimated_minutes as duration FROM learning_path_activities
        WHERE user_id = v_user_id AND is_completed = true
          AND completed_at >= CURRENT_DATE AND completed_at < CURRENT_DATE + INTERVAL '1 day'
    ) today_combined;

    -- Calculate streak (consecutive days with activity)
    WITH daily_practice AS (
        SELECT DISTINCT practice_date
        FROM (
            SELECT completed_at::date as practice_date FROM test_sessions WHERE user_id = v_user_id AND is_completed = true
            UNION ALL
            SELECT completed_at::date as practice_date FROM learning_path_activities WHERE user_id = v_user_id AND is_completed = true
        ) combined
        ORDER BY practice_date DESC
    ),
    streak_calc AS (
        SELECT
            practice_date,
            practice_date - (ROW_NUMBER() OVER (ORDER BY practice_date DESC))::integer AS grp
        FROM daily_practice
        WHERE practice_date >= CURRENT_DATE - INTERVAL '60 days'
    )
    SELECT COALESCE(COUNT(*), 0)::INTEGER INTO v_streak
    FROM streak_calc
    WHERE grp = (SELECT grp FROM streak_calc WHERE practice_date = CURRENT_DATE LIMIT 1);

    -- Handle case where no test today (check if yesterday had test)
    IF v_streak = 0 THEN
        WITH daily_practice AS (
            SELECT DISTINCT practice_date
            FROM (
                SELECT completed_at::date as practice_date FROM test_sessions WHERE user_id = v_user_id AND is_completed = true
                UNION ALL
                SELECT completed_at::date as practice_date FROM learning_path_activities WHERE user_id = v_user_id AND is_completed = true
            ) combined
            ORDER BY practice_date DESC
        ),
        streak_calc AS (
            SELECT
                practice_date,
                practice_date - (ROW_NUMBER() OVER (ORDER BY practice_date DESC))::integer AS grp
            FROM daily_practice
            WHERE practice_date >= CURRENT_DATE - INTERVAL '60 days'
        )
        SELECT COALESCE(COUNT(*), 0)::INTEGER INTO v_streak
        FROM streak_calc
        WHERE grp = (SELECT grp FROM streak_calc WHERE practice_date = CURRENT_DATE - INTERVAL '1 day' LIMIT 1);
    END IF;

    -- Module averages — abandoned sessions excluded (see is_abandoned_test_session)
    SELECT json_object_agg(test_type, avg_score)
    INTO v_module_averages
    FROM (
        SELECT
            LOWER(test_type) as test_type,
            AVG(score) as avg_score
        FROM test_sessions
        WHERE user_id = v_user_id
          AND is_completed = true
          AND score IS NOT NULL
          AND test_type IS NOT NULL
          AND NOT public.is_abandoned_test_session(test_type, score, actual_duration_seconds, content_data)
        GROUP BY LOWER(test_type)
    ) module_stats;

    -- Weekly data (last 7 days) – filter pushed inside each UNION branch
    SELECT json_agg(day_data ORDER BY day_date)
    INTO v_weekly_data
    FROM (
        SELECT
            d.day_date,
            json_build_object(
                'day', TO_CHAR(d.day_date, 'Dy'),
                'tests', COALESCE(COUNT(combined.completed_at), 0)
            ) as day_data
        FROM generate_series(
            CURRENT_DATE - INTERVAL '6 days',
            CURRENT_DATE,
            INTERVAL '1 day'
        ) AS d(day_date)
        LEFT JOIN (
            SELECT completed_at FROM test_sessions
            WHERE user_id = v_user_id AND is_completed = true
              AND completed_at >= CURRENT_DATE - INTERVAL '6 days'
            UNION ALL
            SELECT completed_at FROM learning_path_activities
            WHERE user_id = v_user_id AND is_completed = true
              AND completed_at >= CURRENT_DATE - INTERVAL '6 days'
        ) combined
            ON combined.completed_at >= d.day_date
            AND combined.completed_at < d.day_date + INTERVAL '1 day'
        GROUP BY d.day_date
    ) weekly;

    -- Daily activity (heatmap)
    SELECT json_object_agg(activity_date, total_count)
    INTO v_daily_activity
    FROM (
        SELECT
            completed_at::date::text as activity_date,
            COUNT(*) as total_count
        FROM (
            SELECT completed_at FROM test_sessions WHERE user_id = v_user_id AND is_completed = true
            UNION ALL
            SELECT completed_at FROM learning_path_activities WHERE user_id = v_user_id AND is_completed = true
        ) combined
        WHERE completed_at >= CURRENT_DATE - INTERVAL '90 days'
        GROUP BY completed_at::date
    ) activity;

    -- Build result
    result := json_build_object(
        'totalTests', v_total_tests,
        'measuredTests', v_measured_tests,
        'abandonedTests', v_abandoned_tests,
        'avgScore', ROUND(v_avg_score::numeric, 1),
        'todayMinutes', v_today_minutes,
        'todayTests', v_today_tests,
        'streak', COALESCE(v_streak, 0),
        'moduleAverages', COALESCE(v_module_averages, '{}'::json),
        'weeklyProgress', COALESCE(v_weekly_data, '[]'::json),
        'dailyActivity', COALESCE(v_daily_activity, '{}'::json)
    );

    RETURN result;
END;
$$;

-- 4. get_recent_sessions — walk-aways are no longer meaningful "recent
-- results" to review, so they are filtered out of the list itself. This also
-- fixes the dashboard's Band Trajectory chart and per-module "latest score",
-- both of which read straight from this RPC's output.
CREATE OR REPLACE FUNCTION public.get_recent_sessions(p_limit integer DEFAULT 8)
RETURNS TABLE(id uuid, passage_id uuid, passage_title text, test_type text, score numeric, completed_at timestamp with time zone, duration_minutes integer)
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
    v_user_id UUID;
BEGIN
    SELECT u.id INTO v_user_id FROM public.users u WHERE u.auth_id = auth.uid();
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated or user not found';
    END IF;

    RETURN QUERY
    SELECT
        ts.id,
        ts.passage_id,
        p.title as passage_title,
        ts.test_type,
        ts.score,
        ts.completed_at,
        ts.duration_minutes
    FROM public.test_sessions ts
    LEFT JOIN public.passages p ON p.id = ts.passage_id
    WHERE ts.user_id = v_user_id
      AND ts.is_completed = true
      AND ts.score IS NOT NULL
      AND NOT public.is_abandoned_test_session(ts.test_type, ts.score, ts.actual_duration_seconds, ts.content_data)
    ORDER BY ts.completed_at DESC
    LIMIT p_limit;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_session_duration_seconds(TEXT, INTEGER, JSONB) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.is_abandoned_test_session(TEXT, NUMERIC, INTEGER, JSONB) TO authenticated, service_role;

-- ============================================================================
-- Source migration: 20260801131058_harden_platform_health_contracts
-- Source ledger: repository
-- ============================================================================
-- Evidence-based platform health contracts.
--
-- Each status is derived from the persisted result of a real learner/admin
-- flow. "Idle" means there was no traffic to judge; it is deliberately not
-- treated as proof that a provider is healthy.

-- Finalization is a single database statement so concurrent idempotent callers
-- cannot lose metadata between a client-side read and update.
CREATE OR REPLACE FUNCTION public.finalize_ai_api_usage(
    p_reservation_id uuid,
    p_tokens_used integer DEFAULT 0,
    p_cached boolean DEFAULT false,
    p_metadata jsonb DEFAULT '{}'::jsonb,
    p_status text DEFAULT 'completed'
)
RETURNS boolean
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO ''
AS $function$
DECLARE
    v_updated bigint;
BEGIN
    IF p_status NOT IN ('completed', 'failed') THEN
        RAISE EXCEPTION 'invalid reservation status' USING ERRCODE = '22023';
    END IF;

    UPDATE public.ai_api_usage
    SET cached = COALESCE(p_cached, false),
        tokens_used = GREATEST(COALESCE(p_tokens_used, 0), 0),
        request_metadata = COALESCE(request_metadata, '{}'::jsonb)
            || COALESCE(p_metadata, '{}'::jsonb)
            || jsonb_build_object(
                'reservationStatus', p_status,
                'finalizedAt', now()
            )
    WHERE id = p_reservation_id
      AND request_metadata->>'reservationStatus' = 'reserved';
    GET DIAGNOSTICS v_updated = ROW_COUNT;
    IF v_updated = 1 THEN
        RETURN true;
    END IF;

    -- Idempotent retries are successful but must never overwrite or downgrade
    -- an already-settled record.
    RETURN EXISTS (
        SELECT 1 FROM public.ai_api_usage
        WHERE id = p_reservation_id
          AND request_metadata->>'reservationStatus' IN ('completed', 'failed')
    );
END;
$function$;

ALTER FUNCTION public.finalize_ai_api_usage(uuid, integer, boolean, jsonb, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.finalize_ai_api_usage(uuid, integer, boolean, jsonb, text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.finalize_ai_api_usage(uuid, integer, boolean, jsonb, text) FROM anon;
REVOKE ALL ON FUNCTION public.finalize_ai_api_usage(uuid, integer, boolean, jsonb, text) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.finalize_ai_api_usage(uuid, integer, boolean, jsonb, text) TO service_role;

CREATE INDEX IF NOT EXISTS idx_ai_api_usage_unsettled_created_at
ON public.ai_api_usage (created_at)
WHERE request_metadata->>'reservationStatus' = 'reserved';

CREATE INDEX IF NOT EXISTS idx_stripe_events_processed_at_status
ON public.stripe_events (processed_at DESC, status);

CREATE OR REPLACE FUNCTION public.get_platform_health(p_hours integer DEFAULT 24)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
    v_since timestamptz;
    v_services jsonb := '[]'::jsonb;
    v_hours integer;
    v_status text;
    v_rate numeric;

    v_t_attempts bigint; v_t_errors bigint; v_t_fallbacks bigint; v_t_loss bigint; v_t_p95 numeric;
    v_p_requested bigint; v_p_completed bigint; v_p_errors bigint; v_p_config bigint; v_p_p95 numeric;
    v_s_attempts bigint; v_s_errors bigint; v_s_cached bigint;
    v_a_attempts bigint; v_a_errors bigint; v_a_cached bigint; v_a_pending bigint;
    v_stuck bigint; v_stuck_users bigint; v_oldest_stuck_minutes numeric;
    v_stripe_events bigint; v_stripe_processed bigint; v_stripe_failed bigint;
    v_stripe_paid bigint; v_stripe_amount numeric;
    v_manual_pending bigint; v_manual_paid bigint; v_manual_oldest_hours numeric;
    v_db_size text; v_connections integer; v_max_connections integer; v_connection_pct numeric;
    v_signups bigint; v_active_users bigint; v_sessions bigint; v_logged_errors bigint;
BEGIN
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Access denied';
    END IF;

    v_hours := LEAST(GREATEST(COALESCE(p_hours, 24), 1), 24 * 90);
    v_since := now() - make_interval(hours => v_hours);

    -- Speech-to-text: observe actual persisted transcription outcomes.
    SELECT
        count(*),
        count(*) FILTER (
            WHERE request_metadata->>'reservationStatus' = 'failed'
               OR request_metadata->>'transcriptionFailed' = 'true'
               OR NULLIF(btrim(COALESCE(request_metadata->>'transcriptionError', '')), '') IS NOT NULL
        ),
        count(*) FILTER (WHERE request_metadata->>'transcriptionProvider' = 'gemini-fallback'),
        count(*) FILTER (
            WHERE request_metadata->>'transcriptionProvider' = 'none'
               OR request_metadata->>'transcriptionFailed' = 'true'
        ),
        percentile_cont(0.95) WITHIN GROUP (
            ORDER BY (request_metadata->>'transcriptionLatencyMs')::numeric
        ) FILTER (WHERE jsonb_typeof(request_metadata->'transcriptionLatencyMs') = 'number')
    INTO v_t_attempts, v_t_errors, v_t_fallbacks, v_t_loss, v_t_p95
    FROM public.ai_api_usage
    WHERE created_at >= v_since
      AND endpoint IN ('transcribeAudio', 'processSpeakingSession')
      AND COALESCE(request_metadata->>'reservationStatus', 'completed') <> 'reserved';

    v_rate := CASE WHEN v_t_attempts > 0 THEN 100.0 * v_t_errors / v_t_attempts ELSE 0 END;
    v_status := CASE
        WHEN v_t_attempts = 0 THEN 'idle'
        WHEN v_t_loss >= 3 OR (v_t_attempts >= 5 AND v_rate >= 25) THEN 'down'
        WHEN v_t_errors > 0 OR (v_t_attempts >= 5 AND 100.0 * v_t_fallbacks / v_t_attempts >= 25) THEN 'degraded'
        ELSE 'operational'
    END;
    v_services := v_services || jsonb_build_object(
        'key', 'speech_transcription', 'label', 'Speech-to-Text', 'category', 'ai',
        'provider', 'Cloudflare Whisper -> Gemini fallback', 'status', v_status,
        'source', 'ai_api_usage transcription outcomes',
        'metrics', jsonb_build_object('attempts', v_t_attempts, 'errors', v_t_errors,
            'errorRate', round(v_rate, 1), 'fallbacks', v_t_fallbacks,
            'unrecoverable', v_t_loss, 'p95LatencyMs', round(COALESCE(v_t_p95, 0))),
        'impact', CASE
            WHEN v_t_loss > 0 THEN v_t_loss || ' answer(s) produced no usable transcript.'
            WHEN v_t_errors > 0 THEN v_t_errors || ' transcription attempt(s) reported an error.'
            WHEN v_t_fallbacks > 0 THEN v_t_fallbacks || ' request(s) recovered through Gemini fallback.'
            WHEN v_t_attempts = 0 THEN 'No completed transcription attempts in this window.'
            ELSE 'Completed transcription attempts succeeded without fallback.' END
    );

    -- Pronunciation scoring: requested versus completed is the contract.
    SELECT
        count(*) FILTER (WHERE request_metadata->>'pronunciationRequested' = 'true'),
        count(*) FILTER (WHERE request_metadata->>'pronunciationRequested' = 'true'
                          AND request_metadata->>'pronunciationCompleted' = 'true'),
        count(*) FILTER (WHERE request_metadata->>'pronunciationRequested' = 'true'
                          AND NULLIF(btrim(COALESCE(request_metadata->>'pronunciationError', '')), '') IS NOT NULL),
        count(*) FILTER (WHERE request_metadata->>'pronunciationRequested' = 'true'
                          AND request_metadata->>'pronunciationError' ILIKE '%not configured%'),
        percentile_cont(0.95) WITHIN GROUP (
            ORDER BY (request_metadata->>'pronunciationLatencyMs')::numeric
        ) FILTER (WHERE request_metadata->>'pronunciationRequested' = 'true'
                    AND jsonb_typeof(request_metadata->'pronunciationLatencyMs') = 'number')
    INTO v_p_requested, v_p_completed, v_p_errors, v_p_config, v_p_p95
    FROM public.ai_api_usage
    WHERE created_at >= v_since;

    v_rate := CASE WHEN v_p_requested > 0 THEN 100.0 * v_p_completed / v_p_requested ELSE 0 END;
    v_status := CASE
        WHEN v_p_config > 0 THEN 'unconfigured'
        WHEN v_p_requested = 0 THEN 'idle'
        WHEN v_p_requested >= 3 AND v_rate < 60 THEN 'down'
        WHEN v_p_errors > 0 OR v_rate < 90 THEN 'degraded'
        ELSE 'operational'
    END;
    v_services := v_services || jsonb_build_object(
        'key', 'pronunciation_assessment', 'label', 'Pronunciation Scoring', 'category', 'ai',
        'provider', 'Azure Speech', 'status', v_status,
        'source', 'ai_api_usage pronunciation outcomes',
        'metrics', jsonb_build_object('requested', v_p_requested, 'completed', v_p_completed,
            'completionRate', round(v_rate, 1), 'errors', v_p_errors,
            'credentialErrors', v_p_config, 'p95LatencyMs', round(COALESCE(v_p_p95, 0))),
        'impact', CASE
            WHEN v_p_config > 0 THEN 'Azure Speech configuration was missing or rejected.'
            WHEN v_p_requested = 0 THEN 'No pronunciation scoring was requested in this window.'
            WHEN v_p_requested > v_p_completed THEN (v_p_requested - v_p_completed) || ' request(s) returned no score.'
            ELSE 'Every requested pronunciation assessment completed.' END
    );

    -- Text-to-speech: failures include explicit browser-fallback responses.
    SELECT count(*),
           count(*) FILTER (WHERE request_metadata->>'reservationStatus' = 'failed'
                              OR request_metadata->>'ttsFallback' = 'true'),
           count(*) FILTER (WHERE cached)
    INTO v_s_attempts, v_s_errors, v_s_cached
    FROM public.ai_api_usage
    WHERE created_at >= v_since AND endpoint = 'synthesizeSpeech'
      AND COALESCE(request_metadata->>'reservationStatus', 'completed') <> 'reserved';
    v_rate := CASE WHEN v_s_attempts > 0 THEN 100.0 * v_s_errors / v_s_attempts ELSE 0 END;
    v_status := CASE
        WHEN v_s_attempts = 0 THEN 'idle'
        WHEN v_s_attempts >= 5 AND v_rate >= 25 THEN 'down'
        WHEN v_s_errors > 0 THEN 'degraded'
        ELSE 'operational' END;
    v_services := v_services || jsonb_build_object(
        'key', 'speech_synthesis', 'label', 'Examiner Voice (TTS)', 'category', 'ai',
        'provider', 'Google TTS', 'status', v_status, 'source', 'ai_api_usage TTS outcomes',
        'metrics', jsonb_build_object('attempts', v_s_attempts, 'errors', v_s_errors,
            'errorRate', round(v_rate, 1), 'cacheHits', v_s_cached),
        'impact', CASE WHEN v_s_attempts = 0 THEN 'No completed TTS attempts in this window.'
            WHEN v_s_errors > 0 THEN v_s_errors || ' prompt(s) fell back to browser speech or failed.'
            ELSE 'Examiner audio completed normally.' END
    );

    -- AI scoring: include both reservation-backed and explicit usage rows.
    SELECT count(*) FILTER (WHERE COALESCE(request_metadata->>'reservationStatus', 'completed') <> 'reserved'),
           count(*) FILTER (WHERE request_metadata->>'reservationStatus' = 'failed'),
           count(*) FILTER (WHERE cached),
           count(*) FILTER (WHERE request_metadata->>'reservationStatus' = 'reserved'
                              AND created_at >= now() - interval '1 hour')
    INTO v_a_attempts, v_a_errors, v_a_cached, v_a_pending
    FROM public.ai_api_usage
    WHERE created_at >= v_since
      AND endpoint IN ('generateDetailedFeedback', 'generateDetailedSpeakingFeedback',
          'evaluateSpeakingTest', 'evaluateGrammarTransfer',
          'generateAdaptiveLearningPath', 'generateStudyRecommendations');
    v_rate := CASE WHEN v_a_attempts > 0 THEN 100.0 * v_a_errors / v_a_attempts ELSE 0 END;
    v_status := CASE WHEN v_a_attempts = 0 AND v_a_pending = 0 THEN 'idle'
        WHEN v_a_attempts >= 5 AND v_rate >= 20 THEN 'down'
        WHEN v_a_errors > 0 THEN 'degraded' ELSE 'operational' END;
    v_services := v_services || jsonb_build_object(
        'key', 'ai_feedback', 'label', 'AI Feedback & Scoring', 'category', 'ai',
        'provider', 'Gemini', 'status', v_status, 'source', 'ai_api_usage scoring outcomes',
        'metrics', jsonb_build_object('attempts', v_a_attempts, 'errors', v_a_errors,
            'errorRate', round(v_rate, 1), 'cacheHits', v_a_cached, 'inFlight', v_a_pending),
        'impact', CASE WHEN v_a_attempts = 0 AND v_a_pending = 0 THEN 'No scoring requests in this window.'
            WHEN v_a_errors > 0 THEN v_a_errors || ' scoring request(s) failed.'
            WHEN v_a_pending > 0 THEN v_a_pending || ' scoring request(s) are currently in flight.'
            ELSE 'Scoring requests completed normally.' END
    );

    -- Stuck reservations are an all-time backlog, independent of chart window.
    SELECT count(*), count(DISTINCT user_id),
           extract(epoch FROM (now() - min(created_at))) / 60
    INTO v_stuck, v_stuck_users, v_oldest_stuck_minutes
    FROM public.ai_api_usage
    WHERE request_metadata->>'reservationStatus' = 'reserved'
      AND created_at < now() - interval '1 hour';
    v_status := CASE WHEN v_stuck = 0 THEN 'operational'
        WHEN v_stuck >= 10 OR COALESCE(v_oldest_stuck_minutes, 0) >= 24 * 60 THEN 'down'
        ELSE 'degraded' END;
    v_services := v_services || jsonb_build_object(
        'key', 'ai_quota_reservations', 'label', 'AI Quota Reservations', 'category', 'ai',
        'provider', 'Internal', 'status', v_status, 'source', 'unsettled ai_api_usage reservations',
        'metrics', jsonb_build_object('stuck', v_stuck, 'usersAffected', v_stuck_users,
            'oldestStuckMinutes', round(COALESCE(v_oldest_stuck_minutes, 0))),
        'impact', CASE WHEN v_stuck = 0 THEN 'All quota reservations settled.'
            ELSE v_stuck || ' reservation(s) across ' || v_stuck_users || ' learner(s) remain unsettled.' END
    );

    -- Stripe: only failed event processing is a fault. Non-payment webhook
    -- types legitimately do not create payment rows.
    SELECT count(*),
           count(*) FILTER (WHERE status = 'processed'),
           count(*) FILTER (WHERE status = 'failed')
    INTO v_stripe_events, v_stripe_processed, v_stripe_failed
    FROM public.stripe_events WHERE processed_at >= v_since;
    SELECT count(*), COALESCE(sum(amount), 0)
    INTO v_stripe_paid, v_stripe_amount
    FROM public.payment_requests
    WHERE created_at >= v_since AND lower(payment_method) = 'stripe' AND status = 'approved';
    v_rate := CASE WHEN v_stripe_events > 0 THEN 100.0 * v_stripe_failed / v_stripe_events ELSE 0 END;
    v_status := CASE WHEN v_stripe_events = 0 AND v_stripe_paid = 0 THEN 'idle'
        WHEN v_stripe_events >= 3 AND v_rate >= 25 THEN 'down'
        WHEN v_stripe_failed > 0 THEN 'degraded' ELSE 'operational' END;
    v_services := v_services || jsonb_build_object(
        'key', 'payments_stripe', 'label', 'Card Payments', 'category', 'payments',
        'provider', 'Stripe', 'status', v_status, 'source', 'stripe_events and payment_requests',
        'metrics', jsonb_build_object('webhookEvents', v_stripe_events,
            'processedEvents', v_stripe_processed, 'failedEvents', v_stripe_failed,
            'eventFailureRate', round(v_rate, 1), 'recordedPayments', v_stripe_paid,
            'recordedAmount', v_stripe_amount),
        'impact', CASE WHEN v_stripe_events = 0 AND v_stripe_paid = 0 THEN 'No Stripe activity in this window.'
            WHEN v_stripe_failed > 0 THEN v_stripe_failed || ' Stripe event(s) failed processing.'
            ELSE 'Observed Stripe events processed without recorded failures.' END
    );

    -- Manual payments: backlog is all-time; throughput is window-scoped.
    SELECT count(*) FILTER (WHERE status = 'pending'),
           count(*) FILTER (WHERE status = 'approved' AND lower(payment_method) <> 'stripe'
                              AND created_at >= v_since),
           extract(epoch FROM (now() - min(created_at) FILTER (WHERE status = 'pending'))) / 3600
    INTO v_manual_pending, v_manual_paid, v_manual_oldest_hours
    FROM public.payment_requests;
    v_status := CASE WHEN v_manual_pending = 0 THEN 'operational'
        WHEN COALESCE(v_manual_oldest_hours, 0) > 48 THEN 'down'
        WHEN COALESCE(v_manual_oldest_hours, 0) > 12 THEN 'degraded' ELSE 'attention' END;
    v_services := v_services || jsonb_build_object(
        'key', 'payments_manual', 'label', 'Manual Payments (bKash/Nagad)', 'category', 'payments',
        'provider', 'Admin review', 'status', v_status, 'source', 'payment_requests review queue',
        'metrics', jsonb_build_object('pending', v_manual_pending, 'approvedInWindow', v_manual_paid,
            'oldestPendingHours', round(COALESCE(v_manual_oldest_hours, 0), 1)),
        'impact', CASE WHEN v_manual_pending = 0 THEN 'No payment requests are waiting for review.'
            ELSE v_manual_pending || ' request(s) await review; oldest is ' ||
                 round(COALESCE(v_manual_oldest_hours, 0), 1) || ' hours old.' END
    );

    -- Content readiness requires an active passage, questions, and listening
    -- audio where applicable—not merely an is_active flag.
    v_services := v_services || (
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
            'key', 'content_' || c.test_type,
            'label', initcap(c.test_type) || ' Content', 'category', 'content',
            'provider', 'Test library',
            'status', CASE WHEN c.ready_passages = 0 THEN 'down'
                           WHEN c.broken_passages > 0 OR c.ready_passages < 3 THEN 'degraded'
                           ELSE 'operational' END,
            'source', 'active passages with required questions and audio',
            'metrics', jsonb_build_object('activePassages', c.active_passages,
                'readyPassages', c.ready_passages, 'brokenPassages', c.broken_passages,
                'sessionsInWindow', c.sessions),
            'impact', CASE WHEN c.ready_passages = 0 THEN 'No learner-ready ' || c.test_type || ' tests are available.'
                WHEN c.broken_passages > 0 THEN c.broken_passages || ' active test(s) are missing questions or required audio.'
                ELSE c.ready_passages || ' learner-ready tests are available.' END
        ) ORDER BY c.test_type), '[]'::jsonb)
        FROM (
            SELECT m.test_type,
                count(p.id) FILTER (WHERE p.is_active) AS active_passages,
                count(p.id) FILTER (WHERE p.is_active
                    AND EXISTS (SELECT 1 FROM public.questions q WHERE q.passage_id = p.id)
                    AND (m.test_type <> 'listening' OR NULLIF(btrim(p.audio_url), '') IS NOT NULL)) AS ready_passages,
                count(p.id) FILTER (WHERE p.is_active AND (
                    NOT EXISTS (SELECT 1 FROM public.questions q WHERE q.passage_id = p.id)
                    OR (m.test_type = 'listening' AND NULLIF(btrim(p.audio_url), '') IS NULL))) AS broken_passages,
                (SELECT count(*) FROM public.test_sessions s
                  WHERE s.test_type = m.test_type AND s.created_at >= v_since) AS sessions
            FROM (VALUES ('reading'), ('listening'), ('writing'), ('speaking')) AS m(test_type)
            LEFT JOIN public.passages p ON p.test_type = m.test_type
            GROUP BY m.test_type
        ) c
    );

    -- A successful RPC proves the database is reachable; connection pressure
    -- determines whether it is nominal, degraded, or near exhaustion.
    SELECT pg_catalog.pg_size_pretty(pg_catalog.pg_database_size(pg_catalog.current_database()))
    INTO v_db_size;
    SELECT count(*) INTO v_connections FROM pg_catalog.pg_stat_activity;
    v_max_connections := current_setting('max_connections')::integer;
    v_connection_pct := CASE WHEN v_max_connections > 0 THEN 100.0 * v_connections / v_max_connections ELSE 0 END;
    v_status := CASE WHEN v_connection_pct >= 90 THEN 'down'
        WHEN v_connection_pct >= 70 THEN 'degraded' ELSE 'operational' END;
    v_services := v_services || jsonb_build_object(
        'key', 'database', 'label', 'Database', 'category', 'platform',
        'provider', 'Supabase Postgres', 'status', v_status, 'source', 'pg_stat_activity',
        'metrics', jsonb_build_object('size', v_db_size, 'connections', v_connections,
            'maxConnections', v_max_connections, 'connectionUtilization', round(v_connection_pct, 1)),
        'impact', CASE WHEN v_connection_pct >= 90 THEN 'Connection capacity is nearly exhausted.'
            WHEN v_connection_pct >= 70 THEN 'Connection utilization is elevated.'
            ELSE 'Database reachable; connection utilization is within threshold.' END
    );

    SELECT count(*) INTO v_signups FROM public.users WHERE created_at >= v_since;
    SELECT count(*) INTO v_active_users FROM public.users WHERE last_active >= v_since;
    SELECT count(*) INTO v_sessions FROM public.test_sessions WHERE created_at >= v_since;
    SELECT count(*) INTO v_logged_errors FROM public.system_health_logs
      WHERE created_at >= v_since AND level IN ('error', 'critical');

    RETURN jsonb_build_object(
        'generatedAt', now(), 'windowHours', v_hours, 'contractVersion', 2,
        'services', v_services,
        'activity', jsonb_build_object('signups', v_signups, 'activeUsers', v_active_users,
            'testSessions', v_sessions, 'loggedErrors', v_logged_errors),
        'summary', (SELECT COALESCE(jsonb_object_agg(status, n), '{}'::jsonb)
                    FROM (SELECT s->>'status' status, count(*) n
                          FROM jsonb_array_elements(v_services) s GROUP BY 1) x)
    );
END;
$function$;

REVOKE ALL ON FUNCTION public.get_platform_health(integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_platform_health(integer) FROM anon;
GRANT EXECUTE ON FUNCTION public.get_platform_health(integer) TO authenticated;

CREATE OR REPLACE FUNCTION public.get_platform_health_incidents(
    p_hours integer DEFAULT 24,
    p_limit integer DEFAULT 50
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
    v_since timestamptz;
    v_result jsonb;
BEGIN
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Access denied';
    END IF;
    v_since := now() - make_interval(hours => LEAST(GREATEST(COALESCE(p_hours, 24), 1), 24 * 90));

    SELECT COALESCE(jsonb_agg(to_jsonb(i) ORDER BY i.last_seen DESC, i.occurrences DESC), '[]'::jsonb)
    INTO v_result
    FROM (
        SELECT service, left(message, 500) AS message, count(*) occurrences,
               max(seen_at) last_seen, min(seen_at) first_seen
        FROM (
            SELECT CASE
                       WHEN endpoint IN ('transcribeAudio', 'processSpeakingSession') THEN 'speech_transcription'
                       WHEN endpoint = 'synthesizeSpeech' THEN 'speech_synthesis'
                       WHEN endpoint IN ('generateDetailedFeedback', 'generateDetailedSpeakingFeedback',
                           'evaluateSpeakingTest', 'evaluateGrammarTransfer',
                           'generateAdaptiveLearningPath', 'generateStudyRecommendations') THEN 'ai_feedback'
                       ELSE 'ai_quota_reservations'
                   END AS service,
                   COALESCE(NULLIF(btrim(request_metadata->>'transcriptionError'), ''),
                            NULLIF(btrim(request_metadata->>'ttsError'), ''),
                            NULLIF(btrim(request_metadata->>'failureReason'), ''),
                            'AI request failed') AS message,
                   created_at AS seen_at
            FROM public.ai_api_usage
            WHERE created_at >= v_since AND request_metadata->>'reservationStatus' = 'failed'

            UNION ALL
            SELECT 'pronunciation_assessment', btrim(request_metadata->>'pronunciationError'), created_at
            FROM public.ai_api_usage
            WHERE created_at >= v_since
              AND NULLIF(btrim(COALESCE(request_metadata->>'pronunciationError', '')), '') IS NOT NULL

            UNION ALL
            SELECT 'payments_stripe', COALESCE(NULLIF(btrim(error_message), ''), 'Stripe event failed'), processed_at
            FROM public.stripe_events
            WHERE processed_at >= v_since AND status = 'failed'

            UNION ALL
            SELECT 'system_log:' || COALESCE(component, 'unknown'), message, created_at
            FROM public.system_health_logs
            WHERE created_at >= v_since AND level IN ('error', 'critical')
        ) events
        WHERE NULLIF(btrim(message), '') IS NOT NULL
        GROUP BY service, left(message, 500)
        ORDER BY max(seen_at) DESC, count(*) DESC
        LIMIT LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200)
    ) i;
    RETURN v_result;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_platform_health_incidents(integer, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_platform_health_incidents(integer, integer) FROM anon;
GRANT EXECUTE ON FUNCTION public.get_platform_health_incidents(integer, integer) TO authenticated;

-- ============================================================================
-- Source migration: 20260801133539_fix_admin_overview_accuracy
-- Source ledger: repository
-- ============================================================================
-- Keep every Admin Overview metric on an explicit, internally consistent
-- contract. The selected range is based on Bangladesh calendar days because
-- that is the operating timezone shown by the dashboard.

CREATE OR REPLACE FUNCTION public.get_admin_overview(p_days integer DEFAULT 7)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
    v_days integer;
    v_since timestamptz;
    v_prev timestamptz;

    v_signups bigint; v_signups_prev bigint;
    v_dau bigint; v_active bigint; v_mau bigint; v_active_prev bigint;
    v_total_users bigint;
    v_pro bigint; v_premium bigint;
    v_rev_usd numeric; v_rev_bdt numeric; v_rev_usd_prev numeric;
    v_ai_cost numeric; v_ai_cost_prev numeric; v_ai_priced bigint; v_ai_total bigint;

    v_f_signed bigint; v_f_onboarded bigint; v_f_started bigint;
    v_f_completed bigint; v_f_paid bigint; v_f_subscribed bigint;

    v_pending_pay bigint; v_pending_oldest numeric;
    v_stuck bigint; v_cancelling bigint; v_expiring bigint; v_eval_failed bigint;

    v_started_users bigint; v_repeat_users bigint; v_power_users bigint;
    v_completed_tests bigint;
    v_mock bigint; v_practice bigint; v_other_modes bigint;

    v_trend jsonb; v_modules jsonb; v_recent jsonb; v_actions jsonb := '[]'::jsonb;
    v_retention jsonb; v_hours jsonb;
BEGIN
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Access denied';
    END IF;

    v_days := LEAST(GREATEST(COALESCE(p_days, 7), 1), 90);
    v_since := (
        date_trunc('day', now() AT TIME ZONE 'Asia/Dhaka')
        - make_interval(days => v_days - 1)
    ) AT TIME ZONE 'Asia/Dhaka';
    v_prev := v_since - make_interval(days => v_days);

    -- Users: selected-window activity changes with the range selector. DAU and
    -- MAU remain fixed reference measures for the stickiness calculation.
    SELECT
        count(*),
        count(*) FILTER (WHERE created_at >= v_since),
        count(*) FILTER (WHERE created_at >= v_prev AND created_at < v_since),
        count(*) FILTER (WHERE last_active > now() - interval '1 day'),
        count(*) FILTER (WHERE last_active >= v_since),
        count(*) FILTER (WHERE last_active > now() - interval '30 days'),
        count(*) FILTER (WHERE last_active >= v_prev AND last_active < v_since),
        count(*) FILTER (WHERE subscription_tier = 'pro'),
        count(*) FILTER (WHERE subscription_tier = 'premium'),
        count(*) FILTER (WHERE onboarding_completed),
        count(*) FILTER (WHERE cancel_at_period_end IS TRUE
                           AND subscription_tier IN ('pro','premium')),
        count(*) FILTER (WHERE subscription_tier IN ('pro','premium')
                           AND subscription_end_date IS NOT NULL
                           AND subscription_end_date BETWEEN now() AND now() + interval '7 days')
    INTO v_total_users, v_signups, v_signups_prev, v_dau, v_active, v_mau,
         v_active_prev, v_pro, v_premium, v_f_onboarded, v_cancelling, v_expiring
    FROM public.users;

    v_f_signed := v_total_users;
    v_f_paid := v_pro + v_premium;

    -- Funnel and engagement-depth measures are all-time. Unit economics use
    -- completions from the same selected window as the AI-cost numerator.
    SELECT
        count(DISTINCT ts.user_id) FILTER (WHERE u.onboarding_completed),
        count(DISTINCT ts.user_id) FILTER (WHERE u.onboarding_completed AND ts.is_completed),
        count(*) FILTER (
            WHERE ts.is_completed
              AND COALESCE(ts.completed_at, ts.created_at) >= v_since
        ),
        count(*) FILTER (WHERE ts.test_mode = 'mock'),
        count(*) FILTER (WHERE ts.test_mode = 'practice'),
        count(*) FILTER (WHERE ts.test_mode IS NULL OR ts.test_mode NOT IN ('mock','practice')),
        count(*) FILTER (WHERE ts.evaluation_status = 'failed')
    INTO v_f_started, v_f_completed, v_completed_tests, v_mock, v_practice,
         v_other_modes, v_eval_failed
    FROM public.test_sessions ts
    JOIN public.users u ON u.id = ts.user_id;

    SELECT count(*) INTO v_f_subscribed
    FROM public.users u
    WHERE u.onboarding_completed
      AND u.subscription_tier IN ('pro','premium')
      AND EXISTS (
          SELECT 1
          FROM public.test_sessions ts
          WHERE ts.user_id = u.id
            AND ts.is_completed
      );

    SELECT
        count(*),
        count(*) FILTER (WHERE n >= 2),
        count(*) FILTER (WHERE n >= 5)
    INTO v_started_users, v_repeat_users, v_power_users
    FROM (
        SELECT ts.user_id, count(*) AS n
        FROM public.test_sessions ts
        JOIN public.users u ON u.id = ts.user_id
        GROUP BY ts.user_id
    ) s;

    -- Currency, not payment provider, determines which monetary total receives
    -- a payment. Dedupe matching payment requests against billing history.
    WITH paid AS (
        SELECT bh.amount, upper(bh.currency) AS currency, bh.created_at
        FROM public.billing_history bh
        WHERE bh.status = 'paid'
        UNION ALL
        SELECT pr.amount, upper(pr.currency) AS currency, pr.created_at
        FROM public.payment_requests pr
        WHERE pr.status = 'approved'
          AND NOT EXISTS (
              SELECT 1
              FROM public.billing_history b
              WHERE b.status = 'paid'
                AND b.transaction_id IS NOT NULL
                AND b.transaction_id = pr.transaction_id
          )
    )
    SELECT
        COALESCE(sum(amount) FILTER (WHERE currency = 'USD' AND created_at >= v_since), 0),
        COALESCE(sum(amount) FILTER (WHERE currency = 'BDT' AND created_at >= v_since), 0),
        COALESCE(sum(amount) FILTER (
            WHERE currency = 'USD' AND created_at >= v_prev AND created_at < v_since
        ), 0)
    INTO v_rev_usd, v_rev_bdt, v_rev_usd_prev
    FROM paid;

    -- This remains tracked provider cost, not an invoice total. Coverage makes
    -- the unpriced portion explicit.
    SELECT
        COALESCE(sum((request_metadata->>'estimatedProviderCostUsd')::numeric)
                 FILTER (WHERE jsonb_typeof(request_metadata->'estimatedProviderCostUsd') = 'number'
                           AND created_at >= v_since), 0),
        COALESCE(sum((request_metadata->>'estimatedProviderCostUsd')::numeric)
                 FILTER (WHERE jsonb_typeof(request_metadata->'estimatedProviderCostUsd') = 'number'
                           AND created_at >= v_prev AND created_at < v_since), 0),
        count(*) FILTER (WHERE jsonb_typeof(request_metadata->'estimatedProviderCostUsd') = 'number'
                           AND created_at >= v_since),
        count(*) FILTER (WHERE created_at >= v_since)
    INTO v_ai_cost, v_ai_cost_prev, v_ai_priced, v_ai_total
    FROM public.ai_api_usage;

    SELECT
        count(*) FILTER (WHERE status = 'pending'),
        COALESCE(extract(epoch FROM (now() - min(created_at) FILTER (WHERE status = 'pending'))) / 3600, 0)
    INTO v_pending_pay, v_pending_oldest
    FROM public.payment_requests;

    SELECT count(*) INTO v_stuck
    FROM public.ai_api_usage
    WHERE request_metadata->>'reservationStatus' = 'reserved'
      AND created_at < now() - interval '1 hour'
      AND created_at >= now() - interval '30 days';

    IF v_pending_pay > 0 THEN
        v_actions := v_actions || jsonb_build_object(
            'key','pending_payments','label','Payment requests awaiting review',
            'count',v_pending_pay,'severity','high',
            'detail','Payment evidence was submitted and is waiting for admin verification.',
            'tab','payments');
    END IF;
    IF v_stuck > 0 THEN
        v_actions := v_actions || jsonb_build_object(
            'key','stuck_reservations','label','Stuck AI reservations',
            'count',v_stuck,'severity',CASE WHEN v_stuck >= 10 THEN 'high' ELSE 'medium' END,
            'detail','Quota was consumed but the request never completed.','tab','ai-usage');
    END IF;
    IF v_eval_failed > 0 THEN
        v_actions := v_actions || jsonb_build_object(
            'key','eval_failed','label','Test evaluations failed',
            'count',v_eval_failed,'severity','high',
            'detail','Learners finished a test but never received a score.','tab','ai-usage');
    END IF;
    IF v_cancelling > 0 THEN
        v_actions := v_actions || jsonb_build_object(
            'key','cancelling','label','Subscriptions set to cancel',
            'count',v_cancelling,'severity','medium',
            'detail','Will not renew at the end of the current period.','tab','users');
    END IF;
    IF v_expiring > 0 THEN
        v_actions := v_actions || jsonb_build_object(
            'key','expiring','label','Subscriptions expiring within 7 days',
            'count',v_expiring,'severity','low','detail','Renewal or outreach window.','tab','users');
    END IF;

    -- Historical app-wide DAU cannot be reconstructed from users.last_active,
    -- which stores only the latest visit. Show distinct test takers instead.
    WITH spine AS (
        SELECT generate_series(
            (v_since AT TIME ZONE 'Asia/Dhaka')::date,
            (now() AT TIME ZONE 'Asia/Dhaka')::date,
            interval '1 day'
        )::date AS day
    ),
    su AS (
        SELECT (created_at AT TIME ZONE 'Asia/Dhaka')::date AS day, count(*) AS n
        FROM public.users
        WHERE created_at >= v_since
        GROUP BY 1
    ),
    testers AS (
        SELECT (created_at AT TIME ZONE 'Asia/Dhaka')::date AS day,
               count(DISTINCT user_id) AS n,
               count(*) AS sessions
        FROM public.test_sessions
        WHERE created_at >= v_since
        GROUP BY 1
    )
    SELECT jsonb_agg(jsonb_build_object(
               'date', to_char(spine.day, 'Mon DD'),
               'signups', COALESCE(su.n, 0),
               'testUsers', COALESCE(testers.n, 0),
               'sessions', COALESCE(testers.sessions, 0)
           ) ORDER BY spine.day)
    INTO v_trend
    FROM spine
    LEFT JOIN su ON su.day = spine.day
    LEFT JOIN testers ON testers.day = spine.day;

    -- Future retention weeks are NULL, not zero. Zero is reserved for a mature
    -- week in which nobody in the cohort ran a test.
    WITH cohort AS (
        SELECT id, date_trunc('week', created_at AT TIME ZONE 'Asia/Dhaka')::date AS wk
        FROM public.users
        WHERE created_at >= (
            date_trunc('week', now() AT TIME ZONE 'Asia/Dhaka') - interval '5 weeks'
        ) AT TIME ZONE 'Asia/Dhaka'
    ),
    act AS (
        SELECT DISTINCT user_id,
               date_trunc('week', created_at AT TIME ZONE 'Asia/Dhaka')::date AS wk
        FROM public.test_sessions
        WHERE created_at >= (
            date_trunc('week', now() AT TIME ZONE 'Asia/Dhaka') - interval '5 weeks'
        ) AT TIME ZONE 'Asia/Dhaka'
    ),
    joined AS (
        SELECT c.wk AS cohort_wk,
               c.id,
               ((a.wk - c.wk) / 7)::int AS week_offset
        FROM cohort c
        LEFT JOIN act a ON a.user_id = c.id AND a.wk >= c.wk
    ),
    rolled AS (
        SELECT cohort_wk,
               count(DISTINCT id) AS size,
               count(DISTINCT id) FILTER (WHERE week_offset = 0) AS w0,
               count(DISTINCT id) FILTER (WHERE week_offset = 1) AS w1,
               count(DISTINCT id) FILTER (WHERE week_offset = 2) AS w2,
               count(DISTINCT id) FILTER (WHERE week_offset = 3) AS w3
        FROM joined
        GROUP BY cohort_wk
    ),
    current_week AS (
        SELECT date_trunc('week', now() AT TIME ZONE 'Asia/Dhaka')::date AS wk
    )
    SELECT jsonb_agg(jsonb_build_object(
               'cohort', to_char(rolled.cohort_wk, 'Mon DD'),
               'size', rolled.size,
               'w0', rolled.w0,
               'w1', CASE WHEN rolled.cohort_wk <= current_week.wk - 7 THEN rolled.w1 END,
               'w2', CASE WHEN rolled.cohort_wk <= current_week.wk - 14 THEN rolled.w2 END,
               'w3', CASE WHEN rolled.cohort_wk <= current_week.wk - 21 THEN rolled.w3 END
           ) ORDER BY rolled.cohort_wk)
    INTO v_retention
    FROM rolled
    CROSS JOIN current_week;

    WITH hrs AS (SELECT generate_series(0, 23) AS h),
    s AS (
        SELECT extract(hour FROM created_at AT TIME ZONE 'Asia/Dhaka')::int AS h, count(*) AS n
        FROM public.test_sessions
        WHERE created_at >= now() - interval '30 days'
        GROUP BY 1
    )
    SELECT jsonb_agg(jsonb_build_object('hour', hrs.h, 'sessions', COALESCE(s.n, 0)) ORDER BY hrs.h)
    INTO v_hours
    FROM hrs
    LEFT JOIN s ON s.h = hrs.h;

    SELECT jsonb_agg(t ORDER BY t.sessions DESC)
    INTO v_modules
    FROM (
        SELECT initcap(lower(test_type)) AS module,
               count(DISTINCT user_id) AS users,
               count(*) AS sessions,
               COALESCE(round(100.0 * count(*) FILTER (WHERE is_completed) / NULLIF(count(*), 0), 1), 0) AS completion
        FROM public.test_sessions
        WHERE test_type IS NOT NULL
        GROUP BY lower(test_type)
    ) t;

    SELECT jsonb_agg(t ORDER BY t.created_at DESC)
    INTO v_recent
    FROM (
        SELECT id, full_name, email, created_at, subscription_tier, onboarding_completed
        FROM public.users
        ORDER BY created_at DESC
        LIMIT 8
    ) t;

    RETURN jsonb_build_object(
        'generatedAt', now(),
        'windowDays', v_days,
        'trendMetric', 'testUsers',
        'hourTimezone', 'Asia/Dhaka',
        'kpis', jsonb_build_object(
            'signups', jsonb_build_object('value', v_signups, 'prev', v_signups_prev),
            'active', jsonb_build_object(
                'value', v_active, 'dau', v_dau, 'mau', v_mau, 'prev', v_active_prev,
                'stickiness', CASE WHEN v_mau > 0 THEN round(100.0 * v_dau / v_mau, 1) ELSE 0 END
            ),
            'paying', jsonb_build_object(
                'pro', v_pro, 'premium', v_premium, 'total', v_f_paid,
                'conversion', CASE WHEN v_total_users > 0
                              THEN round(100.0 * v_f_paid / v_total_users, 1) ELSE 0 END
            ),
            'revenue', jsonb_build_object(
                'usd', v_rev_usd, 'bdt', v_rev_bdt, 'prevUsd', v_rev_usd_prev
            ),
            'aiCost', jsonb_build_object(
                'usd', round(v_ai_cost, 4), 'prevUsd', round(v_ai_cost_prev, 4),
                'pricedCalls', v_ai_priced, 'totalCalls', v_ai_total,
                'perActiveUser', CASE WHEN v_active > 0 THEN round(v_ai_cost / v_active, 4) ELSE 0 END
            )
        ),
        'economics', jsonb_build_object(
            'costPerCompletedTest', CASE WHEN v_completed_tests > 0
                                      THEN round(v_ai_cost / v_completed_tests, 4) ELSE 0 END,
            'costPerPayingUser', CASE WHEN v_f_paid > 0
                                   THEN round(v_ai_cost / v_f_paid, 4) ELSE 0 END,
            'completedTests', v_completed_tests,
            'costCoverage', CASE WHEN v_ai_total > 0
                              THEN round(100.0 * v_ai_priced / v_ai_total, 1) ELSE 0 END
        ),
        'engagement', jsonb_build_object(
            'startedUsers', v_started_users,
            'repeatUsers', v_repeat_users,
            'powerUsers', v_power_users,
            'repeatRate', CASE WHEN v_started_users > 0
                           THEN round(100.0 * v_repeat_users / v_started_users, 1) ELSE 0 END,
            'mockSessions', v_mock,
            'practiceSessions', v_practice,
            'otherModeSessions', v_other_modes
        ),
        'funnel', jsonb_build_array(
            jsonb_build_object('key','signed_up','label','Signed up','users',v_f_signed),
            jsonb_build_object('key','onboarded','label','Finished onboarding','users',v_f_onboarded),
            jsonb_build_object('key','started','label','Started a test','users',v_f_started),
            jsonb_build_object('key','completed','label','Completed a test','users',v_f_completed),
            jsonb_build_object(
                'key','paid','label','Completed + subscribed','users',v_f_subscribed
            )
        ),
        'actions', v_actions,
        'trend', COALESCE(v_trend, '[]'::jsonb),
        'retention', COALESCE(v_retention, '[]'::jsonb),
        'hourly', COALESCE(v_hours, '[]'::jsonb),
        'modules', COALESCE(v_modules, '[]'::jsonb),
        'recentSignups', COALESCE(v_recent, '[]'::jsonb),
        'totals', jsonb_build_object('users', v_total_users)
    );
END;
$function$;

REVOKE ALL ON FUNCTION public.get_admin_overview(integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_admin_overview(integer) FROM anon;
GRANT EXECUTE ON FUNCTION public.get_admin_overview(integer) TO authenticated;

COMMENT ON FUNCTION public.get_admin_overview(integer) IS
'Admin landing-page snapshot with range-aligned KPIs, costs, trends, mature retention cells, and currency-correct revenue.';

-- ============================================================================
-- Source migration: 20260801134131_expand_platform_health_coverage
-- Source ledger: repository
-- ============================================================================
-- Add persisted evidence for communication jobs and extend Platform Health to
-- cover account provisioning, learner result delivery, email dispatch, and
-- scheduled automation. The existing v2 health functions remain as internal
-- core collectors so this migration does not duplicate their service logic.

CREATE TABLE IF NOT EXISTS public.email_delivery_events (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at timestamptz NOT NULL DEFAULT now(),
    email_type text NOT NULL,
    recipient_hash text,
    status text NOT NULL,
    provider_message_id text,
    error_message text,
    CONSTRAINT email_delivery_events_status_check
        CHECK (status IN ('accepted', 'failed', 'skipped'))
);

CREATE TABLE IF NOT EXISTS public.scheduled_email_runs (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    started_at timestamptz NOT NULL DEFAULT now(),
    completed_at timestamptz,
    status text NOT NULL DEFAULT 'running',
    candidates integer NOT NULL DEFAULT 0,
    accepted integer NOT NULL DEFAULT 0,
    skipped integer NOT NULL DEFAULT 0,
    failed integer NOT NULL DEFAULT 0,
    error_message text,
    CONSTRAINT scheduled_email_runs_status_check
        CHECK (status IN ('running', 'completed', 'failed')),
    CONSTRAINT scheduled_email_runs_counts_check
        CHECK (candidates >= 0 AND accepted >= 0 AND skipped >= 0 AND failed >= 0)
);

ALTER TABLE public.email_delivery_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.scheduled_email_runs ENABLE ROW LEVEL SECURITY;

