-- ============================================================================
-- Source migration: 20260801144159_secure_scheduled_email_cron
-- Source ledger: repository
-- ============================================================================
-- Secure scheduled messaging with a purpose-specific random credential stored
-- in Vault. The Edge Function verifies this credential through a service-role
-- RPC, so the cron definition never contains the project's service-role key.

DO $block$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM vault.decrypted_secrets WHERE name = 'project_url'
    ) THEN
        PERFORM vault.create_secret(
            'https://zvrmvycajimjxghrnpgy.supabase.co',
            'project_url',
            'Supabase project URL used by database scheduled jobs'
        );
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM vault.decrypted_secrets WHERE name = 'scheduled_email_token'
    ) THEN
        PERFORM vault.create_secret(
            encode(extensions.gen_random_bytes(32), 'hex'),
            'scheduled_email_token',
            'Dedicated credential for the scheduled-emails Edge Function'
        );
    END IF;
END;
$block$;

CREATE OR REPLACE FUNCTION public.verify_scheduled_email_token(p_token text)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $function$
    SELECT
        COALESCE(auth.jwt()->>'role', '') = 'service_role'
        AND p_token IS NOT NULL
        AND EXISTS (
            SELECT 1
            FROM vault.decrypted_secrets
            WHERE name = 'scheduled_email_token'
              AND extensions.digest(decrypted_secret, 'sha256') =
                  extensions.digest(p_token, 'sha256')
        );
$function$;

REVOKE ALL ON FUNCTION public.verify_scheduled_email_token(text)
    FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.verify_scheduled_email_token(text)
    TO service_role;

DO $block$
DECLARE
    v_job_id bigint;
BEGIN
    SELECT jobid INTO v_job_id
    FROM cron.job
    WHERE jobname = 'daily-scheduled-emails';

    IF v_job_id IS NOT NULL THEN
        PERFORM cron.unschedule(v_job_id);
    END IF;
END;
$block$;

SELECT cron.schedule(
    'daily-scheduled-emails',
    '0 0 * * *',
    $cron$
    SELECT net.http_post(
        url := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'project_url')
            || '/functions/v1/scheduled-emails',
        headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'X-Scheduler-Secret',
            (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'scheduled_email_token')
        ),
        body := '{}'::jsonb,
        timeout_milliseconds := 30000
    ) AS request_id;
    $cron$
);

-- ============================================================================
-- Source migration: 20260801144922_reflect_scheduled_email_recovery
-- Source ledger: repository
-- ============================================================================
-- A newly repaired cron job has no run history yet. Represent that evidence as
-- degraded/pending verification rather than a false outage; a queued cron run
-- without an application telemetry row will still be reported as down.

ALTER FUNCTION public.get_platform_health(integer)
    RENAME TO get_platform_health_core_v4;
REVOKE ALL ON FUNCTION public.get_platform_health_core_v4(integer)
    FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.get_platform_health(p_hours integer DEFAULT 24)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
    v_base jsonb;
    v_services jsonb;
BEGIN
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Access denied';
    END IF;

    v_base := public.get_platform_health_core_v4(p_hours);

    SELECT COALESCE(jsonb_agg(
        CASE
            WHEN service->>'key' = 'scheduled_automation'
              AND service->'metrics'->>'cronActive' = 'true'
              AND service->'metrics'->'lastCronStatus' = 'null'::jsonb
              AND service->'metrics'->>'lastRunRecorded' = 'false'
            THEN service || jsonb_build_object(
                'status', 'degraded',
                'impact', 'The repaired scheduler is active and passed its authenticated endpoint check; the first scheduled application run is still pending.'
            )
            ELSE service
        END
    ), '[]'::jsonb)
    INTO v_services
    FROM jsonb_array_elements(COALESCE(v_base->'services', '[]'::jsonb)) service;

    v_base := jsonb_set(v_base, '{services}', v_services, true);
    v_base := jsonb_set(v_base, '{contractVersion}', '5'::jsonb, true);
    v_base := jsonb_set(v_base, '{summary}', (
        SELECT COALESCE(jsonb_object_agg(status, n), '{}'::jsonb)
        FROM (
            SELECT service->>'status' AS status, count(*) AS n
            FROM jsonb_array_elements(v_services) service
            GROUP BY service->>'status'
        ) counts
    ), true);

    RETURN v_base;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_platform_health(integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_platform_health(integer) TO authenticated;

-- ============================================================================
-- Source migration: 20260801145150_backfill_confirmed_orphan_profiles
-- Source ledger: repository
-- ============================================================================
-- Restore learner profiles only for established Auth accounts that proved they
-- were real by confirming their email and signing in. Unconfirmed or never-used
-- historical accounts remain untouched for manual retention review.

INSERT INTO public.users (
    auth_id,
    email,
    full_name,
    created_at,
    updated_at
)
SELECT
    account.id,
    account.email,
    COALESCE(
        NULLIF(btrim(account.raw_user_meta_data->>'full_name'), ''),
        NULLIF(split_part(account.email, '@', 1), ''),
        'User'
    ),
    account.created_at,
    now()
FROM auth.users account
LEFT JOIN public.users profile ON profile.auth_id = account.id
WHERE profile.id IS NULL
  AND account.email IS NOT NULL
  AND account.email_confirmed_at IS NOT NULL
  AND account.last_sign_in_at IS NOT NULL;

-- ============================================================================
-- Source migration: 20260801145252_classify_auth_provisioning_health
-- Source ledger: repository
-- ============================================================================
-- Missing profiles affect service health only when the Auth account is
-- established (confirmed or previously signed in). Never-activated historical
-- accounts remain visible as inventory without producing a false outage.

ALTER FUNCTION public.get_platform_health(integer)
    RENAME TO get_platform_health_core_v5;
REVOKE ALL ON FUNCTION public.get_platform_health_core_v5(integer)
    FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.get_platform_health(p_hours integer DEFAULT 24)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
    v_base jsonb;
    v_services jsonb;
    v_actionable bigint := 0;
    v_unactivated bigint := 0;
    v_oldest_actionable_hours numeric;
BEGIN
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Access denied';
    END IF;

    v_base := public.get_platform_health_core_v5(p_hours);

    SELECT
        count(*) FILTER (WHERE account.email_confirmed_at IS NOT NULL
            OR account.last_sign_in_at IS NOT NULL),
        count(*) FILTER (WHERE account.email_confirmed_at IS NULL
            AND account.last_sign_in_at IS NULL),
        extract(epoch FROM (now() - min(account.created_at) FILTER (
            WHERE account.email_confirmed_at IS NOT NULL
               OR account.last_sign_in_at IS NOT NULL
        ))) / 3600
    INTO v_actionable, v_unactivated, v_oldest_actionable_hours
    FROM auth.users account
    LEFT JOIN public.users profile ON profile.auth_id = account.id
    WHERE profile.id IS NULL
      AND account.created_at < now() - interval '15 minutes';

    SELECT COALESCE(jsonb_agg(
        CASE WHEN service->>'key' = 'auth_provisioning' THEN
            jsonb_set(
                service || jsonb_build_object(
                    'status', CASE
                        WHEN v_actionable >= 10 THEN 'down'
                        WHEN v_actionable > 0 THEN 'degraded'
                        ELSE 'operational'
                    END,
                    'impact', CASE WHEN v_actionable = 0 THEN
                        'No confirmed or previously signed-in Auth account is missing a learner profile. ' ||
                        v_unactivated || ' unactivated historical account(s) remain available for retention review.'
                    ELSE
                        v_actionable || ' established Auth account(s) have no learner profile and may be unable to use the app.'
                    END
                ),
                '{metrics}',
                (service->'metrics') || jsonb_build_object(
                    'actionableProfileGaps', v_actionable,
                    'unactivatedAccounts', v_unactivated,
                    'oldestActionableHours', CASE
                        WHEN v_oldest_actionable_hours IS NULL THEN 'null'::jsonb
                        ELSE to_jsonb(round(v_oldest_actionable_hours, 1))
                    END
                ),
                true
            )
        ELSE service END
    ), '[]'::jsonb)
    INTO v_services
    FROM jsonb_array_elements(COALESCE(v_base->'services', '[]'::jsonb)) service;

    v_base := jsonb_set(v_base, '{services}', v_services, true);
    v_base := jsonb_set(v_base, '{contractVersion}', '6'::jsonb, true);
    v_base := jsonb_set(v_base, '{summary}', (
        SELECT COALESCE(jsonb_object_agg(status, n), '{}'::jsonb)
        FROM (
            SELECT service->>'status' AS status, count(*) AS n
            FROM jsonb_array_elements(v_services) service
            GROUP BY service->>'status'
        ) counts
    ), true);

    RETURN v_base;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_platform_health(integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_platform_health(integer) TO authenticated;

-- ============================================================================
-- Source migration: 20260801172127_optimize_learning_path_data_rpc
-- Source ledger: repository
-- ============================================================================
-- Keep the personalized Learning Path on one authenticated database round trip.
-- The previous RPC omitted fields added by the evidence-aware activity contract,
-- which forced the client to discard its activities/proficiencies and re-query
-- both tables. It also returned every session in a 90-day window including
-- abandoned attempts. This contract returns the current fields and a bounded,
-- measured evidence window while preserving all-time measured test counts.

CREATE OR REPLACE FUNCTION public.get_learning_path_data()
RETURNS json
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
    v_user_id uuid;
    v_path record;
    v_activities json;
    v_module_averages json;
    v_module_trends json;
    v_sessions json;
    v_proficiencies json;
    v_total_tests integer;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Authentication required' USING errcode = '42501';
    END IF;

    SELECT profile.id
    INTO v_user_id
    FROM public.users AS profile
    WHERE profile.auth_id = auth.uid();

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Profile not found' USING errcode = '42501';
    END IF;

    SELECT path.id, path.path_data, path.activities_completed, path.created_at
    INTO v_path
    FROM public.learning_paths AS path
    WHERE path.user_id = v_user_id
    ORDER BY path.created_at DESC
    LIMIT 1;

    SELECT COALESCE(
        pg_catalog.json_agg(
            pg_catalog.json_build_object(
                'id', activity.id,
                'activity_key', activity.activity_key,
                'scheduled_day', activity.scheduled_day,
                'scheduled_date', activity.scheduled_date,
                'stage_key', activity.stage_key,
                'completion_policy', activity.completion_policy,
                'requested_mode', activity.requested_mode,
                'evidence_key', activity.evidence_key,
                'is_completed', activity.is_completed,
                'completed_at', activity.completed_at,
                'outcome_score', activity.outcome_score,
                'outcome_band', activity.outcome_band,
                'outcome_accuracy', activity.outcome_accuracy,
                'completion_source', activity.completion_source,
                'outcome_data', activity.outcome_data,
                'title', activity.title,
                'description', activity.description,
                'module', activity.module,
                'estimated_minutes', activity.estimated_minutes,
                'priority', activity.priority,
                'activity_type', activity.activity_type,
                'skill_targets', activity.skill_targets
            )
            ORDER BY activity.scheduled_date NULLS LAST, activity.scheduled_day, activity.created_at
        ),
        '[]'::json
    )
    INTO v_activities
    FROM public.learning_path_activities AS activity
    WHERE activity.learning_path_id = v_path.id;

    WITH recent_sessions AS (
        SELECT
            session.test_type,
            session.score,
            session.completed_at,
            pg_catalog.row_number() OVER (
                PARTITION BY pg_catalog.lower(session.test_type)
                ORDER BY session.completed_at DESC
            ) AS sequence
        FROM public.test_sessions AS session
        WHERE session.user_id = v_user_id
          AND session.is_completed = true
          AND session.score IS NOT NULL
          AND session.completed_at >= pg_catalog.now() - interval '90 days'
          AND NOT public.is_abandoned_test_session(
              session.test_type,
              session.score,
              session.actual_duration_seconds,
              session.content_data
          )
    ), module_stats AS (
        SELECT
            pg_catalog.lower(test_type) AS test_type,
            pg_catalog.avg(score) AS average_score,
            pg_catalog.max(score) FILTER (WHERE sequence = 1) AS latest_score,
            pg_catalog.max(score) FILTER (WHERE sequence = 2) AS previous_score
        FROM recent_sessions
        GROUP BY pg_catalog.lower(test_type)
    )
    SELECT
        COALESCE(
            pg_catalog.json_object_agg(
                test_type,
                pg_catalog.round(average_score::numeric, 2)
            ),
            '{}'::json
        ),
        COALESCE(
            pg_catalog.json_object_agg(
                test_type,
                CASE
                    WHEN latest_score > previous_score THEN 'up'
                    WHEN latest_score < previous_score THEN 'down'
                    ELSE 'stable'
                END
            ),
            '{}'::json
        )
    INTO v_module_averages, v_module_trends
    FROM module_stats;

    SELECT pg_catalog.count(*)::integer
    INTO v_total_tests
    FROM public.test_sessions AS session
    WHERE session.user_id = v_user_id
      AND session.is_completed = true
      AND session.score IS NOT NULL
      AND NOT public.is_abandoned_test_session(
          session.test_type,
          session.score,
          session.actual_duration_seconds,
          session.content_data
      );

    SELECT COALESCE(
        pg_catalog.json_agg(
            pg_catalog.json_build_object(
                'id', session_row.id,
                'test_type', session_row.test_type,
                'score', session_row.score,
                'completed_at', session_row.completed_at,
                'content_data', session_row.content_data
            )
            ORDER BY session_row.completed_at DESC
        ),
        '[]'::json
    )
    INTO v_sessions
    FROM (
        SELECT recent.id, recent.test_type, recent.score, recent.completed_at, recent.content_data
        FROM public.test_sessions AS recent
        WHERE recent.user_id = v_user_id
          AND recent.is_completed = true
          AND recent.completed_at >= pg_catalog.now() - interval '90 days'
          AND NOT public.is_abandoned_test_session(
              recent.test_type,
              recent.score,
              recent.actual_duration_seconds,
              recent.content_data
          )
        ORDER BY recent.completed_at DESC
        LIMIT 40
    ) AS session_row;

    SELECT COALESCE(
        pg_catalog.json_agg(
            pg_catalog.json_build_object(
                'skill_code', proficiency.skill_code,
                'module', proficiency.module,
                'mastery_probability', proficiency.mastery_probability,
                'confidence_level', proficiency.confidence_level,
                'practice_count', proficiency.practice_count,
                'correct_count', proficiency.correct_count,
                'last_practiced_at', proficiency.last_practiced_at,
                'next_review_at', proficiency.next_review_at,
                'evidence_version', proficiency.evidence_version
            )
            ORDER BY proficiency.mastery_probability ASC
        ),
        '[]'::json
    )
    INTO v_proficiencies
    FROM (
        SELECT current_skill.*
        FROM public.skill_proficiency AS current_skill
        WHERE current_skill.user_id = v_user_id
        ORDER BY current_skill.mastery_probability ASC
        LIMIT 100
    ) AS proficiency;

    RETURN pg_catalog.json_build_object(
        'learningPath', CASE
            WHEN v_path.id IS NULL THEN NULL
            ELSE pg_catalog.json_build_object(
                'id', v_path.id,
                'path_data', v_path.path_data,
                'activities_completed', v_path.activities_completed,
                'created_at', v_path.created_at
            )
        END,
        'activities', COALESCE(v_activities, '[]'::json),
        'stats', pg_catalog.json_build_object(
            'moduleAverages', COALESCE(v_module_averages, '{}'::json),
            'moduleTrends', COALESCE(v_module_trends, '{}'::json),
            'totalTests', COALESCE(v_total_tests, 0),
            'sessions', COALESCE(v_sessions, '[]'::json)
        ),
        'skillProficiencies', COALESCE(v_proficiencies, '[]'::json)
    );
END;
$$;

REVOKE ALL ON FUNCTION public.get_learning_path_data() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_learning_path_data() TO authenticated, service_role;

COMMENT ON FUNCTION public.get_learning_path_data() IS
  'Returns the current authenticated learner path, activities, measured recent evidence, and skill proficiencies in one bounded call.';

-- ============================================================================
-- Source migration: 20260801222509_add_text_ai_provider_health
-- Source ledger: repository
-- ============================================================================
-- Evidence-based text AI provider health for the admin Health screen.
--
-- This is deliberately telemetry-only: the database never probes a provider
-- with a secret and never exposes secret configuration state. A provider is
-- judged from completed, persisted Edge Function outcomes.

CREATE OR REPLACE FUNCTION public.get_ai_provider_health(p_hours integer DEFAULT 24)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
    v_since timestamptz;
    v_hours integer;
    v_attempts bigint;
    v_errors bigint;
    v_fallbacks bigint;
    v_openrouter bigint;
    v_direct_deepseek bigint;
    v_gemini bigint;
    v_unknown bigint;
    v_cost numeric;
    v_rate numeric;
    v_status text;
BEGIN
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Access denied';
    END IF;

    v_hours := LEAST(GREATEST(COALESCE(p_hours, 24), 1), 24 * 90);
    v_since := now() - make_interval(hours => v_hours);

    SELECT
        count(*) FILTER (
            WHERE COALESCE(request_metadata->>'reservationStatus', 'completed') <> 'reserved'
        ),
        count(*) FILTER (
            WHERE request_metadata->>'reservationStatus' = 'failed'
        ),
        count(*) FILTER (
            WHERE request_metadata->>'fallbackUsed' = 'true'
        ),
        count(*) FILTER (
            WHERE request_metadata->>'provider' = 'openrouter-deepseek'
        ),
        count(*) FILTER (
            WHERE request_metadata->>'provider' = 'deepseek'
        ),
        count(*) FILTER (
            WHERE request_metadata->>'provider' = 'gemini'
        ),
        count(*) FILTER (
            WHERE NULLIF(btrim(request_metadata->>'provider'), '') IS NULL
        ),
        COALESCE(sum(
            CASE
                WHEN request_metadata->>'estimatedProviderCostUsd' ~ '^[0-9]+(\.[0-9]+)?$'
                THEN (request_metadata->>'estimatedProviderCostUsd')::numeric
                ELSE 0
            END
        ), 0)
    INTO v_attempts, v_errors, v_fallbacks, v_openrouter, v_direct_deepseek,
         v_gemini, v_unknown, v_cost
    FROM public.ai_api_usage
    WHERE created_at >= v_since
      AND endpoint IN (
          'evaluateGrammarTransfer',
          'generateAdaptiveLearningPath',
          'generateStudyRecommendations',
          'generateDetailedFeedback',
          'generateDetailedSpeakingFeedback',
          'evaluateSpeakingTest'
      );

    v_rate := CASE WHEN v_attempts > 0 THEN 100.0 * v_errors / v_attempts ELSE 0 END;
    v_status := CASE
        WHEN v_attempts = 0 THEN 'idle'
        WHEN v_attempts >= 5 AND v_rate >= 20 THEN 'down'
        WHEN v_errors > 0 OR v_fallbacks > 0 THEN 'degraded'
        ELSE 'operational'
    END;

    RETURN jsonb_build_object(
        'generatedAt', now(),
        'windowHours', v_hours,
        'service', jsonb_build_object(
            'key', 'ai_text_providers',
            'label', 'Text AI Providers',
            'category', 'ai',
            'provider', 'OpenRouter DeepSeek -> Direct DeepSeek -> Gemini',
            'status', v_status,
            'source', 'ai_api_usage provider telemetry',
            'metrics', jsonb_build_object(
                'attempts', v_attempts,
                'errors', v_errors,
                'errorRate', round(v_rate, 1),
                'fallbacks', v_fallbacks,
                'openrouterCalls', v_openrouter,
                'directDeepseekCalls', v_direct_deepseek,
                'geminiCalls', v_gemini,
                'unknownProviderCalls', v_unknown,
                'estimatedCostUsd', round(v_cost, 6)
            ),
            'impact', CASE
                WHEN v_attempts = 0 THEN 'No text AI requests in this window; this is not proof of provider health.'
                WHEN v_errors > 0 THEN v_errors || ' text AI request(s) failed.'
                WHEN v_fallbacks > 0 THEN v_fallbacks || ' request(s) recovered through a fallback provider.'
                ELSE 'Text AI requests completed without fallback.'
            END
        )
    );
END;
$function$;

REVOKE ALL ON FUNCTION public.get_ai_provider_health(integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_ai_provider_health(integer) FROM anon;
GRANT EXECUTE ON FUNCTION public.get_ai_provider_health(integer) TO authenticated;

COMMENT ON FUNCTION public.get_ai_provider_health(integer) IS
'Admin-only telemetry view of text AI provider routing and fallback outcomes; never probes providers or exposes secrets.';

-- ============================================================================
-- Source migration: 20260802120000_unify_admin_communications
-- Source ledger: repository
-- ============================================================================
-- Unify the three global "the platform is talking to its users" surfaces:
-- broadcast notifications, the site-wide banner, and maintenance mode.
--
-- Before this migration:
-- * `notifications` rows were readable by every authenticated user regardless
--   of audience, schedule or expiry, and read state lived in a single global
--   `is_read` boolean shared by all users — so it could never work per person.
-- * `maintenance_mode` was a bare boolean with nowhere to put a message, an
--   ETA, or an operator allowlist.
-- * `public_announcement` had no schedule, link, or audience.
--
-- All three now carry the options the admin panel needs, and the old shapes are
-- migrated in place so nothing has to be re-entered.

-- ---------------------------------------------------------------------------
-- Broadcast notifications: scheduling, links, priority, pause
-- ---------------------------------------------------------------------------

ALTER TABLE public.notifications
  ADD COLUMN IF NOT EXISTS starts_at timestamp with time zone DEFAULT now(),
  ADD COLUMN IF NOT EXISTS link_url text,
  ADD COLUMN IF NOT EXISTS link_label text,
  ADD COLUMN IF NOT EXISTS priority text DEFAULT 'normal',
  ADD COLUMN IF NOT EXISTS is_active boolean DEFAULT true NOT NULL,
  ADD COLUMN IF NOT EXISTS updated_at timestamp with time zone DEFAULT now();

UPDATE public.notifications SET starts_at = created_at WHERE starts_at IS NULL;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'notifications_priority_check'
  ) THEN
    ALTER TABLE public.notifications
      ADD CONSTRAINT notifications_priority_check
      CHECK (priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text]));
  END IF;
END $$;

COMMENT ON COLUMN public.notifications.starts_at IS
  'When the broadcast becomes visible. Lets an admin queue an announcement ahead of a launch.';
COMMENT ON COLUMN public.notifications.is_active IS
  'Pause switch. Hides the broadcast from learners without deleting the record or its read history.';

CREATE INDEX IF NOT EXISTS idx_notifications_delivery_window
  ON public.notifications USING btree (is_active, starts_at, expires_at);

-- The old global `is_read` column could never represent per-user state; it is
-- superseded by notification_reads below and kept only so any straggling
-- client that still selects it does not error.
COMMENT ON COLUMN public.notifications.is_read IS
  'DEPRECATED - global flag, never per-user. Use public.notification_reads instead.';

-- ---------------------------------------------------------------------------
-- Per-user read / dismiss state
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS public.notification_reads (
  notification_id uuid NOT NULL REFERENCES public.notifications(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  read_at timestamp with time zone DEFAULT now(),
  dismissed_at timestamp with time zone,
  PRIMARY KEY (notification_id, user_id)
);

COMMENT ON TABLE public.notification_reads IS
  'Per-user read and dismiss state for broadcast notifications.';

CREATE INDEX IF NOT EXISTS idx_notification_reads_user
  ON public.notification_reads USING btree (user_id);

ALTER TABLE public.notification_reads ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS notification_reads_owner_select ON public.notification_reads;
CREATE POLICY notification_reads_owner_select
  ON public.notification_reads FOR SELECT TO authenticated
  USING (user_id = (SELECT auth.uid()) OR (SELECT public.is_admin()));

DROP POLICY IF EXISTS notification_reads_owner_insert ON public.notification_reads;
CREATE POLICY notification_reads_owner_insert
  ON public.notification_reads FOR INSERT TO authenticated
  WITH CHECK (user_id = (SELECT auth.uid()));

DROP POLICY IF EXISTS notification_reads_owner_update ON public.notification_reads;
CREATE POLICY notification_reads_owner_update
  ON public.notification_reads FOR UPDATE TO authenticated
  USING (user_id = (SELECT auth.uid()))
  WITH CHECK (user_id = (SELECT auth.uid()));

DROP POLICY IF EXISTS notification_reads_owner_delete ON public.notification_reads;
CREATE POLICY notification_reads_owner_delete
  ON public.notification_reads FOR DELETE TO authenticated
  USING (user_id = (SELECT auth.uid()));

REVOKE ALL ON TABLE public.notification_reads FROM PUBLIC;
REVOKE ALL ON TABLE public.notification_reads FROM anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.notification_reads TO authenticated;
GRANT ALL ON TABLE public.notification_reads TO service_role;

-- ---------------------------------------------------------------------------
-- Audience-aware delivery
-- ---------------------------------------------------------------------------

-- SECURITY DEFINER so the notifications policy can read the caller's tier
-- without depending on public.users' own row-level policies.
CREATE OR REPLACE FUNCTION public.current_subscription_tier()
RETURNS text
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT COALESCE(
    (SELECT u.subscription_tier FROM public.users u WHERE u.auth_id = auth.uid() LIMIT 1),
    'free'
  );
$$;

COMMENT ON FUNCTION public.current_subscription_tier() IS
  'Subscription tier of the calling user, defaulting to free. Used by notification audience targeting.';

REVOKE ALL ON FUNCTION public.current_subscription_tier() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.current_subscription_tier() TO authenticated;
GRANT EXECUTE ON FUNCTION public.current_subscription_tier() TO service_role;

-- Previously `USING (true)`: every signed-in user could read every broadcast,
-- including ones scheduled for the future, already expired, or aimed at a tier
-- they are not on. Audience targeting was applied in the browser only.
DROP POLICY IF EXISTS notifications_select_policy ON public.notifications;
CREATE POLICY notifications_select_policy
  ON public.notifications FOR SELECT TO authenticated
  USING (
    (SELECT public.is_admin())
    OR (
      is_active
      AND (starts_at IS NULL OR starts_at <= now())
      AND (expires_at IS NULL OR expires_at > now())
      AND (
        target_audience = 'all'
        OR target_audience = (SELECT public.current_subscription_tier())
      )
    )
  );

-- ---------------------------------------------------------------------------
-- Maintenance mode: boolean -> configurable object
-- ---------------------------------------------------------------------------

INSERT INTO public.system_settings (key, value, description)
VALUES (
  'maintenance_mode',
  jsonb_build_object(
    'enabled', false,
    'title', 'We''ll be right back',
    'message', 'IELTS AI Pro is undergoing scheduled maintenance. Your progress is safe and everything will be exactly where you left it.',
    'starts_at', NULL,
    'ends_at', NULL,
    'auto_resume', false,
    'allow_admins', true,
    'allowed_emails', '[]'::jsonb,
    'contact_email', '',
    'status_url', ''
  ),
  'Site-wide maintenance mode: enablement, learner-facing copy, window, and bypass allowlist.'
)
ON CONFLICT (key) DO UPDATE
SET
  description = EXCLUDED.description,
  value = CASE
    -- Legacy shape: a bare JSON boolean. Preserve whether it was switched on.
    WHEN jsonb_typeof(public.system_settings.value) = 'boolean'
      THEN jsonb_set(EXCLUDED.value, '{enabled}', public.system_settings.value)
    -- Already an object: keep the operator's values, add any missing keys.
    WHEN jsonb_typeof(public.system_settings.value) = 'object'
      THEN EXCLUDED.value || public.system_settings.value
    ELSE EXCLUDED.value
  END;

-- ---------------------------------------------------------------------------
-- Public announcement: add schedule, link, audience, dismissibility
-- ---------------------------------------------------------------------------

INSERT INTO public.system_settings (key, value, description)
VALUES (
  'public_announcement',
  jsonb_build_object(
    'enabled', false,
    'title', '',
    'message', '',
    'type', 'info',
    'link_url', '',
    'link_label', '',
    'dismissible', true,
    'starts_at', NULL,
    'ends_at', NULL,
    'audience', 'all'
  ),
  'Site-wide announcement banner: copy, severity, call to action, schedule, and audience.'
)
ON CONFLICT (key) DO UPDATE
SET
  description = EXCLUDED.description,
  value = CASE
    WHEN jsonb_typeof(public.system_settings.value) = 'object'
      THEN EXCLUDED.value || public.system_settings.value
    ELSE EXCLUDED.value
  END;

-- The banner used to store 'error' as its most severe level while broadcast
-- notifications used 'warning'; one vocabulary now (info/success/warning/critical).
UPDATE public.system_settings
SET value = jsonb_set(value, '{type}', '"critical"'::jsonb)
WHERE key = 'public_announcement'
  AND jsonb_typeof(value) = 'object'
  AND value ->> 'type' = 'error';

