-- Source migration: 20260809042731_checkout_recovery_engine
-- Source ledger: repository
-- ============================================================================
-- Checkout recovery: send a consent-aware, single-use 15% offer roughly two
-- hours after the learner's *latest* unfinished checkout. Offers are issued to
-- one public profile only; a forwarded email code cannot be redeemed elsewhere.

ALTER TABLE public.promo_codes
  ADD COLUMN IF NOT EXISTS assigned_user_id uuid REFERENCES public.users(id) ON DELETE CASCADE,
  ADD COLUMN IF NOT EXISTS marketing_delivery_id uuid REFERENCES public.marketing_deliveries(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS offer_expires_at timestamptz;

CREATE UNIQUE INDEX IF NOT EXISTS promo_codes_checkout_recovery_recipient_idx
  ON public.promo_codes (marketing_campaign_id, assigned_user_id)
  WHERE assigned_user_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS promo_codes_checkout_recovery_expiry_idx
  ON public.promo_codes (offer_expires_at)
  WHERE offer_expires_at IS NOT NULL;

-- A checkout recovery audience is based on the latest checkout event, never an
-- older abandoned attempt. This prevents a new checkout from receiving its
-- reminder early because of a previous incomplete attempt.
CREATE OR REPLACE FUNCTION public.marketing_segment_members(
  p_segment_id uuid,
  p_require_marketing_consent boolean DEFAULT false,
  p_limit integer DEFAULT 1000
)
RETURNS TABLE(
  user_id uuid,
  email text,
  full_name text,
  subscription_tier text,
  consent_marketing boolean,
  triggered_at timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_rules jsonb;
BEGIN
  IF NOT public.is_admin() AND auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;

  SELECT rules INTO v_rules FROM public.marketing_segments WHERE id = p_segment_id AND is_active;
  IF v_rules IS NULL THEN RETURN; END IF;

  RETURN QUERY
  WITH usage_month AS (
    SELECT a.user_id, count(*)::integer AS used
    FROM public.ai_api_usage a
    WHERE a.created_at >= date_trunc('month', now())
    GROUP BY a.user_id
  ), completed AS (
    SELECT t.user_id, max(COALESCE(t.completed_at, t.created_at)) AS completed_at
    FROM public.test_sessions t
    WHERE t.is_completed = true OR t.completed_at IS NOT NULL
    GROUP BY t.user_id
  ), quota AS (
    SELECT u.id,
      COALESCE(um.used, 0) AS used,
      COALESCE(trl.writing_monthly_limit, 0) + COALESCE(trl.speaking_monthly_limit, 0)
        + COALESCE(u.bonus_writing_credits, 0) + COALESCE(u.bonus_speaking_credits, 0) AS allowed
    FROM public.users u
    LEFT JOIN usage_month um ON um.user_id = u.id
    LEFT JOIN public.tier_rate_limits trl ON trl.tier = u.subscription_tier
  ), latest_checkout AS (
    SELECT me.user_id, max(me.occurred_at) AS started_at
    FROM public.marketing_events me
    WHERE me.event_type = 'checkout_started'
    GROUP BY me.user_id
  )
  SELECT u.id, u.email, u.full_name, u.subscription_tier, COALESCE(u.consent_marketing, false),
    CASE
      WHEN v_rules ? 'checkout_abandoned_hours_min' THEN COALESCE(lc.started_at, u.created_at)
      WHEN v_rules ? 'payment_failed' THEN COALESCE(u.payment_failed_at, u.updated_at, u.created_at)
      WHEN v_rules ? 'inactive_days_min' THEN COALESCE(u.last_active, u.created_at)
      WHEN v_rules ? 'has_completed_test' AND (v_rules->>'has_completed_test')::boolean
        THEN COALESCE(c.completed_at, u.created_at)
      ELSE u.created_at
    END AS triggered_at
  FROM public.users u
  LEFT JOIN completed c ON c.user_id = u.id
  LEFT JOIN quota q ON q.id = u.id
  LEFT JOIN latest_checkout lc ON lc.user_id = u.id
  WHERE u.role <> 'admin'
    AND (NOT p_require_marketing_consent OR COALESCE(u.consent_marketing, false))
    AND (NOT (v_rules ? 'subscription_tiers') OR u.subscription_tier IN (
      SELECT jsonb_array_elements_text(v_rules->'subscription_tiers')
    ))
    AND (NOT (v_rules ? 'signup_channels') OR COALESCE(u.signup_channel, 'unknown') IN (
      SELECT jsonb_array_elements_text(v_rules->'signup_channels')
    ))
    AND (NOT (v_rules ? 'utm_sources') OR COALESCE(u.signup_utm_source, '') IN (
      SELECT jsonb_array_elements_text(v_rules->'utm_sources')
    ))
    AND (NOT (v_rules ? 'utm_campaigns') OR COALESCE(u.signup_utm_campaign, '') IN (
      SELECT jsonb_array_elements_text(v_rules->'utm_campaigns')
    ))
    AND (NOT (v_rules ? 'landing_pages') OR COALESCE(u.signup_landing_page, '') IN (
      SELECT jsonb_array_elements_text(v_rules->'landing_pages')
    ))
    AND (NOT (v_rules ? 'onboarding_completed') OR u.onboarding_completed = (v_rules->>'onboarding_completed')::boolean)
    AND (NOT (v_rules ? 'has_completed_test') OR (c.user_id IS NOT NULL) = (v_rules->>'has_completed_test')::boolean)
    AND (NOT (v_rules ? 'created_days_max') OR u.created_at >= now() - make_interval(days => (v_rules->>'created_days_max')::integer))
    AND (NOT (v_rules ? 'inactive_days_min') OR COALESCE(u.last_active, u.created_at) <= now() - make_interval(days => (v_rules->>'inactive_days_min')::integer))
    AND (NOT (v_rules ? 'inactive_days_max') OR COALESCE(u.last_active, u.created_at) >= now() - make_interval(days => (v_rules->>'inactive_days_max')::integer))
    AND (NOT (v_rules ? 'payment_failed') OR (u.payment_failed_at IS NOT NULL) = (v_rules->>'payment_failed')::boolean)
    AND (NOT (v_rules ? 'cancel_at_period_end') OR COALESCE(u.cancel_at_period_end, false) = (v_rules->>'cancel_at_period_end')::boolean)
    AND (NOT (v_rules ? 'referral_expiry_days_max') OR u.referral_bonus_expires_at BETWEEN now() AND now() + make_interval(days => (v_rules->>'referral_expiry_days_max')::integer))
    AND (NOT (v_rules ? 'test_date_days_max') OR u.test_date BETWEEN current_date AND current_date + (v_rules->>'test_date_days_max')::integer)
    AND (NOT (v_rules ? 'target_band_min') OR u.target_band_score >= (v_rules->>'target_band_min')::numeric)
    AND (NOT (v_rules ? 'target_band_max') OR u.target_band_score <= (v_rules->>'target_band_max')::numeric)
    AND (NOT (v_rules ? 'weak_modules') OR COALESCE(u.weak_area, '') IN (
      SELECT jsonb_array_elements_text(v_rules->'weak_modules')
    ))
    AND (NOT (v_rules ? 'quota_states') OR
      CASE
        WHEN q.allowed <= q.used THEN 'exhausted'
        WHEN q.allowed - q.used <= 1 THEN 'low'
        ELSE 'available'
      END IN (SELECT jsonb_array_elements_text(v_rules->'quota_states'))
    )
    AND (NOT (v_rules ? 'exclude_active_promo') OR u.promo_discount IS NULL)
    AND (NOT (v_rules ? 'checkout_abandoned_hours_min') OR (
      lc.started_at IS NOT NULL
      AND lc.started_at <= now() - make_interval(hours => (v_rules->>'checkout_abandoned_hours_min')::integer)
      AND NOT EXISTS (
        SELECT 1 FROM public.marketing_events purchase_event
        WHERE purchase_event.user_id = u.id
          AND purchase_event.event_type = 'purchased'
          AND purchase_event.occurred_at > lc.started_at
      )
    ))
    AND (NOT (v_rules ? 'exclude_user_ids') OR NOT (u.id::text = ANY (
      ARRAY(SELECT jsonb_array_elements_text(v_rules->'exclude_user_ids'))
    )))
  ORDER BY u.created_at DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 1000), 1), 10000);
END;
$$;

-- The dispatcher can issue an offer, but no browser role can mint one. A
-- recipient may receive only one offer for this campaign, valid for seven days.
CREATE OR REPLACE FUNCTION public.provision_checkout_recovery_offer(
  p_campaign_id uuid,
  p_user_id uuid,
  p_delivery_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_existing public.promo_codes%ROWTYPE;
  v_user public.users%ROWTYPE;
  v_code text;
  v_expires_at timestamptz := now() + interval '7 days';
BEGIN
  IF auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Service role required' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_user
  FROM public.users
  WHERE id = p_user_id AND role <> 'admin' AND subscription_tier = 'free';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('available', false, 'reason', 'not_free');
  END IF;
  IF v_user.promo_discount IS NOT NULL THEN
    RETURN jsonb_build_object('available', false, 'reason', 'active_promo');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.marketing_deliveries
    WHERE id = p_delivery_id AND campaign_id = p_campaign_id AND user_id = p_user_id AND channel = 'email'
  ) THEN
    RAISE EXCEPTION 'Recovery delivery does not match campaign recipient' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_existing
  FROM public.promo_codes
  WHERE marketing_campaign_id = p_campaign_id AND assigned_user_id = p_user_id
  LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'available', v_existing.is_active AND (v_existing.offer_expires_at IS NULL OR v_existing.offer_expires_at > now()),
      'code', v_existing.code,
      'expires_at', v_existing.offer_expires_at
    );
  END IF;

  v_code := 'BACK15-' || upper(substring(replace(gen_random_uuid()::text, '-', '') FROM 1 FOR 10));
  INSERT INTO public.promo_codes (
    code, discount_type, discount_value, is_active, valid_from, valid_until,
    max_uses, current_uses, marketing_campaign_id, marketing_delivery_id, label,
    assigned_user_id, offer_expires_at
  ) VALUES (
    v_code, 'percentage', 15, true, now(), v_expires_at,
    1, 0, p_campaign_id, p_delivery_id, 'Checkout recovery · 15% · single use',
    p_user_id, v_expires_at
  );

  RETURN jsonb_build_object('available', true, 'code', v_code, 'expires_at', v_expires_at);
END;
$$;

REVOKE ALL ON FUNCTION public.provision_checkout_recovery_offer(uuid, uuid, uuid)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.provision_checkout_recovery_offer(uuid, uuid, uuid) TO service_role;

-- Bind personalised offers to their intended profile during redemption and at
-- checkout validation. The second check protects against any legacy path that
-- could otherwise write promo_discount without the redemption RPC.
CREATE OR REPLACE FUNCTION public.redeem_promo_code(code_lookup text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_auth_id uuid;
  v_profile_id uuid;
  v_promo public.promo_codes%ROWTYPE;
  v_already_used boolean;
BEGIN
  v_auth_id := auth.uid();
  IF v_auth_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not logged in');
  END IF;
  SELECT id INTO v_profile_id FROM public.users WHERE auth_id = v_auth_id;
  IF v_profile_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'User not found');
  END IF;

  SELECT * INTO v_promo
  FROM public.promo_codes
  WHERE upper(code) = upper(trim(code_lookup))
    AND is_active = true
    AND (valid_until IS NULL OR valid_until > now())
    AND (offer_expires_at IS NULL OR offer_expires_at > now())
    AND (assigned_user_id IS NULL OR assigned_user_id = v_profile_id)
    AND (max_uses IS NULL OR current_uses < max_uses);
  IF v_promo IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid or expired promo code');
  END IF;

  SELECT (v_promo.id::text = ANY(COALESCE(used_promo_codes, ARRAY[]::text[])))
  INTO v_already_used
  FROM public.users
  WHERE auth_id = v_auth_id;
  IF COALESCE(v_already_used, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'You have already used this promo code');
  END IF;

  IF v_promo.grants_subscription IS NOT NULL THEN
    UPDATE public.users
    SET subscription_tier = v_promo.grants_subscription,
        promo_discount = NULL,
        used_promo_codes = array_append(COALESCE(used_promo_codes, ARRAY[]::text[]), v_promo.id::text),
        updated_at = now()
    WHERE auth_id = v_auth_id;
    UPDATE public.promo_codes SET current_uses = COALESCE(current_uses, 0) + 1 WHERE id = v_promo.id;
    RETURN jsonb_build_object('success', true, 'type', 'grant', 'subscription', v_promo.grants_subscription,
      'message', 'Subscription ' || initcap(v_promo.grants_subscription) || ' activated successfully!');
  END IF;

  UPDATE public.users
  SET promo_discount = jsonb_build_object(
        'code', v_promo.code,
        'discount_type', v_promo.discount_type,
        'discount_value', v_promo.discount_value,
        'applied_date', now()
      ),
      used_promo_codes = array_append(COALESCE(used_promo_codes, ARRAY[]::text[]), v_promo.id::text),
      updated_at = now()
  WHERE auth_id = v_auth_id;
  UPDATE public.promo_codes SET current_uses = COALESCE(current_uses, 0) + 1 WHERE id = v_promo.id;
  RETURN jsonb_build_object('success', true, 'type', 'discount',
    'discount_type', v_promo.discount_type, 'discount_value', v_promo.discount_value,
    'code', v_promo.code, 'message', 'Discount applied successfully!');
END;
$$;

-- Give the recovery engine a live admin view. Counts are based on the current
-- latest checkout state, while sent and recovered counts are server-attributed.
CREATE OR REPLACE FUNCTION public.get_checkout_recovery_dashboard()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE v_campaign_id uuid;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501'; END IF;
  SELECT id INTO v_campaign_id
  FROM public.marketing_campaigns
  WHERE metadata->>'system_key' = 'journey:checkout_abandoned'
  LIMIT 1;

  RETURN (
    WITH latest_checkout AS (
      SELECT user_id, max(occurred_at) AS started_at
      FROM public.marketing_events
      WHERE event_type = 'checkout_started'
      GROUP BY user_id
    ), open_checkouts AS (
      SELECT lc.user_id, lc.started_at
      FROM latest_checkout lc
      JOIN public.users u ON u.id = lc.user_id
      WHERE u.role <> 'admin'
        AND u.subscription_tier = 'free'
        AND NOT EXISTS (
          SELECT 1 FROM public.marketing_events p
          WHERE p.user_id = lc.user_id AND p.event_type = 'purchased' AND p.occurred_at > lc.started_at
        )
    ), sent AS (
      SELECT DISTINCT user_id
      FROM public.marketing_deliveries
      WHERE campaign_id = v_campaign_id AND channel = 'email' AND status NOT IN ('skipped', 'failed')
    ), recovered AS (
      SELECT DISTINCT user_id
      FROM public.marketing_events
      WHERE campaign_id = v_campaign_id AND event_type = 'purchased'
    )
    SELECT jsonb_build_object(
      'campaign_id', v_campaign_id,
      'waiting', count(*) FILTER (WHERE started_at > now() - interval '2 hours'),
      'eligible', count(*) FILTER (WHERE started_at <= now() - interval '2 hours'),
      'sent', (SELECT count(*) FROM sent),
      'recovered', (SELECT count(*) FROM recovered),
      'conversion_rate', CASE WHEN (SELECT count(*) FROM sent) > 0
        THEN round(100.0 * (SELECT count(*) FROM recovered) / (SELECT count(*) FROM sent), 1)
        ELSE 0 END
    )
    FROM open_checkouts
  );
END;
$$;

REVOKE ALL ON FUNCTION public.get_checkout_recovery_dashboard() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_checkout_recovery_dashboard() TO authenticated, service_role;

UPDATE public.marketing_segments
SET description = 'Free learners whose latest checkout started at least two hours ago without a purchase or active promo.',
    rules = '{"subscription_tiers":["free"],"checkout_abandoned_hours_min":2,"exclude_active_promo":true}'::jsonb,
    is_active = true,
    updated_at = now()
WHERE name = 'Checkout abandoned';

UPDATE public.marketing_campaigns
SET name = 'Checkout recovery · 15% offer',
    status = 'active',
    channels = ARRAY['email']::text[],
    subject = 'Your 15% IELTS plan offer is ready',
    title = 'Your 15% plan offer is ready',
    message = 'You were close to choosing a plan. We saved a one-time 15% offer for you so you can continue with consistent AI feedback and focused IELTS practice when the time is right.',
    cta_label = 'Claim 15% off',
    cta_url = '/pricing',
    promo_code_id = NULL,
    frequency_cap = 1,
    cooldown_hours = 168,
    activated_at = COALESCE(activated_at, now()),
    metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
      'checkout_recovery_offer_percent', 15,
      'checkout_recovery_offer_expiry_days', 7,
      'configured_by', 'checkout_recovery_engine'
    ),
    updated_at = now()
WHERE metadata->>'system_key' = 'journey:checkout_abandoned';

UPDATE public.marketing_journeys
SET is_active = true,
    delay_hours = 0,
    cooldown_hours = 168,
    config = COALESCE(config, '{}'::jsonb) || jsonb_build_object(
      'exit_on', 'purchase',
      'automatic_discount', true,
      'discount_percent', 15,
      'offer_expiry_days', 7,
      'minimum_hours_after_checkout', 2
    ),
    updated_at = now()
WHERE trigger_type = 'checkout_abandoned';

UPDATE public.marketing_campaign_templates
SET description = 'Consent-aware checkout recovery email sent about two hours after the latest unfinished checkout. Issues a one-use 15% offer valid for seven days.',
    channels = ARRAY['email']::text[],
    subject = 'Your 15% IELTS plan offer is ready',
    title = 'Your 15% plan offer is ready',
    message = 'You were close to choosing a plan. We saved a one-time 15% offer for you so you can continue with consistent AI feedback and focused IELTS practice when the time is right.',
    cta_label = 'Claim 15% off',
    cta_url = '/pricing',
    is_active = true,
    updated_at = now()
WHERE name = 'Auto: checkout reminder';

DO $cron$
DECLARE v_job_id bigint;
BEGIN
  SELECT jobid INTO v_job_id FROM cron.job WHERE jobname = 'hourly-marketing-journeys';
  IF v_job_id IS NOT NULL THEN PERFORM cron.unschedule(v_job_id); END IF;
  SELECT jobid INTO v_job_id FROM cron.job WHERE jobname = 'quarter-hour-marketing-journeys';
  IF v_job_id IS NOT NULL THEN PERFORM cron.unschedule(v_job_id); END IF;
END;
$cron$;

SELECT cron.schedule(
  'quarter-hour-marketing-journeys',
  '7,22,37,52 * * * *',
  $cron$
  SELECT net.http_post(
    url := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'project_url')
      || '/functions/v1/marketing-campaign-dispatch',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'X-Scheduler-Secret',
      (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'scheduled_email_token')
    ),
    body := '{"process_journeys":true}'::jsonb,
    timeout_milliseconds := 55000
  ) AS request_id;
  $cron$
);

NOTIFY pgrst, 'reload schema';

-- ============================================================================
-- Source migration: 20260809120000_fix_ai_provider_health_classification
-- Source ledger: repository
-- ============================================================================
-- Text AI provider health: stop reporting a recovered failure as degradation,
-- and attribute calls to the provider that actually served them.
--
-- Two defects this replaces:
--
-- 1. Status. The old CASE degraded the service on
--    `v_errors > 0 OR v_upstream_failures > 0 OR v_fallbacks > 0`.
--    `v_upstream_failures` counts every failed reservation *including* the ones
--    that recovered, so a single self-healed blip rendered the panel as
--    DEGRADED while the same panel showed 0 errors, a 0% error rate, and an
--    impact line reading "learners were not blocked". A fallback firing is the
--    system working, not the system degrading. Degradation now requires either
--    unrecovered errors or a provider failing often enough to be genuinely
--    unreliable.
--
-- 2. Attribution. Provider buckets matched only 'openrouter-deepseek',
--    'deepseek' and 'gemini' against request_metadata->>'provider'. Several
--    endpoints never wrote that key at all (generateDetailedFeedback writes
--    only `model`, and it routes through OpenRouter Luna, which was not in the
--    list), so every call fell into "unknown provider" — 12 of 12 in
--    production. Provider is now resolved from the explicit key, falling back
--    to inferring it from the recorded model so historical rows attribute too,
--    and cache hits are excluded because they call no provider.

CREATE OR REPLACE FUNCTION public.get_ai_provider_health(p_hours integer DEFAULT 24)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
    v_since timestamptz;
    v_hours integer;
    v_attempts bigint;
    v_upstream_failures bigint;
    v_recovered bigint;
    v_errors bigint;
    v_fallbacks bigint;
    v_cached bigint;
    v_openrouter_deepseek bigint;
    v_openrouter_luna bigint;
    v_direct_deepseek bigint;
    v_gemini bigint;
    v_unknown bigint;
    v_cost numeric;
    v_error_rate numeric;
    v_upstream_rate numeric;
    v_status text;
BEGIN
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Access denied';
    END IF;

    v_hours := LEAST(GREATEST(COALESCE(p_hours, 24), 1), 24 * 90);
    v_since := now() - make_interval(hours => v_hours);

    WITH tracked AS (
        SELECT
            request_metadata,
            COALESCE(request_metadata->>'reservationStatus', 'completed') AS res_status,
            COALESCE(request_metadata->>'cached', 'false') = 'true'       AS is_cached,
            -- Explicit provider wins; otherwise infer from the model string so
            -- rows written before providers were recorded still attribute.
            CASE
                WHEN NULLIF(btrim(request_metadata->>'provider'), '') IS NOT NULL
                    THEN btrim(request_metadata->>'provider')
                WHEN request_metadata->>'model' ILIKE '%gemini%'       THEN 'gemini'
                WHEN request_metadata->>'model' ILIKE 'deepseek/%'     THEN 'openrouter-deepseek'
                WHEN request_metadata->>'model' ILIKE '%deepseek%'     THEN 'deepseek'
                WHEN request_metadata->>'model' ILIKE 'openai/%luna%'  THEN 'openrouter-luna'
                ELSE NULL
            END AS provider
        FROM public.ai_api_usage
        WHERE created_at >= v_since
          AND endpoint IN (
              'evaluateGrammarTransfer',
              'generateAdaptiveLearningPath',
              'generateStudyRecommendations',
              'generateDetailedFeedback',
              'generateDetailedSpeakingFeedback',
              'evaluateSpeakingTest'
          )
    ),
    -- Provider attribution only covers rows that actually reached a provider:
    -- a reservation still open has not called one, and a cache hit never will.
    provider_calls AS (
        SELECT * FROM tracked WHERE res_status <> 'reserved' AND NOT is_cached
    )
    SELECT
        (SELECT count(*) FROM tracked WHERE res_status <> 'reserved'),
        (SELECT count(*) FROM tracked WHERE res_status = 'failed'),
        (SELECT count(*) FROM tracked
          WHERE res_status = 'failed'
            AND request_metadata->>'deterministicFallback' = 'true'),
        (SELECT count(*) FROM tracked
          WHERE res_status = 'failed'
            AND COALESCE(request_metadata->>'deterministicFallback', 'false') <> 'true'),
        (SELECT count(*) FROM tracked WHERE request_metadata->>'fallbackUsed' = 'true'),
        (SELECT count(*) FROM tracked WHERE res_status <> 'reserved' AND is_cached),
        (SELECT count(*) FROM provider_calls WHERE provider = 'openrouter-deepseek'),
        (SELECT count(*) FROM provider_calls WHERE provider = 'openrouter-luna'),
        (SELECT count(*) FROM provider_calls WHERE provider = 'deepseek'),
        (SELECT count(*) FROM provider_calls WHERE provider = 'gemini'),
        (SELECT count(*) FROM provider_calls
          WHERE provider IS NULL OR provider NOT IN
                ('openrouter-deepseek', 'openrouter-luna', 'deepseek', 'gemini', 'cache')),
        (SELECT COALESCE(sum(
            CASE
                WHEN request_metadata->>'estimatedProviderCostUsd' ~ '^[0-9]+(\.[0-9]+)?$'
                THEN (request_metadata->>'estimatedProviderCostUsd')::numeric
                ELSE 0
            END
         ), 0) FROM tracked)
    INTO v_attempts, v_upstream_failures, v_recovered, v_errors, v_fallbacks, v_cached,
         v_openrouter_deepseek, v_openrouter_luna, v_direct_deepseek, v_gemini,
         v_unknown, v_cost;

    v_error_rate    := CASE WHEN v_attempts > 0 THEN 100.0 * v_errors / v_attempts ELSE 0 END;
    v_upstream_rate := CASE WHEN v_attempts > 0 THEN 100.0 * v_upstream_failures / v_attempts ELSE 0 END;

    v_status := CASE
        WHEN v_attempts = 0 THEN 'idle'
        -- Unrecovered failures are the only thing a learner actually feels.
        WHEN v_errors >= 3 AND v_error_rate >= 20 THEN 'down'
        WHEN v_errors > 0 THEN 'degraded'
        -- Everything recovered, but a provider failing this often is a real
        -- reliability problem worth surfacing even though nobody was blocked.
        WHEN v_upstream_failures >= 3 AND v_upstream_rate >= 25 THEN 'degraded'
        -- Recovered, and often enough to be worth a look.
        WHEN v_upstream_failures > 0 AND v_upstream_rate >= 10 THEN 'attention'
        -- Recovered and rare. 'attention' renders as "Needs action", which is
        -- false for a self-healed blip — the recovery counts and the impact
        -- line below still carry the detail without raising a flag nobody can
        -- act on.
        ELSE 'operational'
    END;

    RETURN jsonb_build_object(
        'generatedAt', now(),
        'windowHours', v_hours,
        'service', jsonb_build_object(
            'key', 'ai_text_providers',
            'label', 'Text AI Providers',
            'category', 'ai',
            'provider', 'OpenRouter (Luna, DeepSeek) -> Direct DeepSeek -> Gemini',
            'status', v_status,
            'source', 'ai_api_usage provider and recovery outcomes',
            'metrics', jsonb_build_object(
                'attempts', v_attempts,
                'errors', v_errors,
                'errorRate', round(v_error_rate, 1),
                'upstreamFailures', v_upstream_failures,
                'recoveredFallbacks', v_recovered,
                'fallbacks', v_fallbacks,
                'cachedResponses', v_cached,
                'openrouterCalls', v_openrouter_deepseek,
                'openrouterLunaCalls', v_openrouter_luna,
                'directDeepseekCalls', v_direct_deepseek,
                'geminiCalls', v_gemini,
                'unknownProviderCalls', v_unknown,
                'estimatedCostUsd', round(v_cost, 6)
            ),
            'impact', CASE
                WHEN v_attempts = 0 THEN
                    'No text AI requests in this window; this is not proof of provider health.'
                WHEN v_errors > 0 THEN
                    v_errors || ' text AI request(s) failed with no usable result for the learner.'
                WHEN v_upstream_failures >= 3 AND v_upstream_rate >= 25 THEN
                    v_upstream_failures || ' of ' || v_attempts ||
                    ' requests needed recovery. Learners were not blocked, but a provider is failing often enough to investigate.'
                WHEN v_recovered > 0 OR v_fallbacks > 0 THEN
                    GREATEST(v_recovered, v_fallbacks) ||
                    ' request(s) recovered automatically. No learner was blocked and no action is required.'
                ELSE
                    'Text AI requests completed without a recorded provider failure.'
            END
        )
    );
END;
$function$;

REVOKE ALL ON FUNCTION public.get_ai_provider_health(integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_ai_provider_health(integer) TO authenticated;

-- ============================================================================
-- Source migration: 20260809140000_marketing_email_opt_out
-- Source ledger: repository
-- ============================================================================
-- Marketing email: move from opt-in to opt-out, and make unsubscribe real.
--
-- Two problems this fixes.
--
-- 1. The gate was the wrong column. Email eligibility was reading
--    `users.consent_marketing`, which is the *cookie banner's* marketing
--    toggle. It is written only by CookieConsent.jsx / CookieSettings.jsx, no
--    signup step ever set it, and 189 of 190 users had it false — so every
--    marketing email was skipped with 'marketing_consent_required' and the
--    funnel could never move. It also means a learner accepting or rejecting
--    marketing *cookies* silently changed their *email* subscription, which is
--    not what either control claims to do.
--
--    Email now has its own column, `marketing_email_unsubscribed_at`. NULL
--    means subscribed, so every existing and future user is reachable by
--    default and the cookie banner no longer touches email at all.
--
-- 2. Unsubscribe did not work. Every email footer linked to
--    `/settings?tab=preferences`, which is not one of the Settings tabs — the
--    page silently fell back to Profile, so a learner clicking "Unsubscribe"
--    got their profile page and no way to opt out. `unsubscribe_marketing_email`
--    below gives the email a token-authenticated, no-login opt-out that works
--    from the message itself.

-- 1. Opt-out column ---------------------------------------------------------

ALTER TABLE public.users
  ADD COLUMN IF NOT EXISTS marketing_email_unsubscribed_at timestamptz;

COMMENT ON COLUMN public.users.marketing_email_unsubscribed_at IS
  'When the learner opted out of marketing email. NULL means subscribed. '
  'Distinct from consent_marketing, which is the cookie banner''s toggle and '
  'must never gate email.';

-- Partial index: the dispatcher filters on "still subscribed", which is the
-- overwhelming majority, so index the opted-out minority instead.
CREATE INDEX IF NOT EXISTS users_marketing_unsubscribed_idx
  ON public.users (marketing_email_unsubscribed_at)
  WHERE marketing_email_unsubscribed_at IS NOT NULL;

-- 2. Record unsubscribes as first-class funnel events ------------------------

ALTER TABLE public.marketing_events
  DROP CONSTRAINT IF EXISTS marketing_events_event_type_check;
ALTER TABLE public.marketing_events
  ADD CONSTRAINT marketing_events_event_type_check
  CHECK (event_type = ANY (ARRAY[
    'delivered', 'viewed', 'clicked', 'checkout_started',
    'purchased', 'exited', 'failed', 'unsubscribed'
  ]));

-- 3. Segment membership now gates on the email opt-out ----------------------
--
-- The returned `consent_marketing` column keeps its name so the dispatcher and
-- the admin estimate RPC keep working unchanged, but it now answers the only
-- question the caller actually asks of it: may we email this person?

CREATE OR REPLACE FUNCTION public.marketing_segment_members(
  p_segment_id uuid,
  p_require_marketing_consent boolean DEFAULT false,
  p_limit integer DEFAULT 1000
)
RETURNS TABLE(
  user_id uuid,
  email text,
  full_name text,
  subscription_tier text,
  consent_marketing boolean,
  triggered_at timestamp with time zone
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_rules jsonb;
BEGIN
  IF NOT public.is_admin() AND auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'Admin access required' USING ERRCODE = '42501';
  END IF;

  SELECT rules INTO v_rules FROM public.marketing_segments WHERE id = p_segment_id AND is_active;
  IF v_rules IS NULL THEN RETURN; END IF;

  RETURN QUERY
  WITH usage_month AS (
    SELECT a.user_id, count(*)::integer AS used
    FROM public.ai_api_usage a
    WHERE a.created_at >= date_trunc('month', now())
    GROUP BY a.user_id
  ), completed AS (
    SELECT t.user_id, max(COALESCE(t.completed_at, t.created_at)) AS completed_at
    FROM public.test_sessions t
    WHERE t.is_completed = true OR t.completed_at IS NOT NULL
    GROUP BY t.user_id
  ), quota AS (
    SELECT u.id,
      COALESCE(um.used, 0) AS used,
      COALESCE(trl.writing_monthly_limit, 0) + COALESCE(trl.speaking_monthly_limit, 0)
        + COALESCE(u.bonus_writing_credits, 0) + COALESCE(u.bonus_speaking_credits, 0) AS allowed
    FROM public.users u
    LEFT JOIN usage_month um ON um.user_id = u.id
    LEFT JOIN public.tier_rate_limits trl ON trl.tier = u.subscription_tier
  ), latest_checkout AS (
    SELECT me.user_id, max(me.occurred_at) AS started_at
    FROM public.marketing_events me
    WHERE me.event_type = 'checkout_started'
    GROUP BY me.user_id
  )
  SELECT u.id, u.email, u.full_name, u.subscription_tier,
    (u.marketing_email_unsubscribed_at IS NULL),
    CASE
      WHEN v_rules ? 'checkout_abandoned_hours_min' THEN COALESCE(lc.started_at, u.created_at)
      WHEN v_rules ? 'payment_failed' THEN COALESCE(u.payment_failed_at, u.updated_at, u.created_at)
      WHEN v_rules ? 'inactive_days_min' THEN COALESCE(u.last_active, u.created_at)
      WHEN v_rules ? 'has_completed_test' AND (v_rules->>'has_completed_test')::boolean
        THEN COALESCE(c.completed_at, u.created_at)
      ELSE u.created_at
    END AS triggered_at
  FROM public.users u
  LEFT JOIN completed c ON c.user_id = u.id
  LEFT JOIN quota q ON q.id = u.id
  LEFT JOIN latest_checkout lc ON lc.user_id = u.id
  WHERE u.role <> 'admin'
    AND (NOT p_require_marketing_consent OR u.marketing_email_unsubscribed_at IS NULL)
    AND (NOT (v_rules ? 'subscription_tiers') OR u.subscription_tier IN (
      SELECT jsonb_array_elements_text(v_rules->'subscription_tiers')
    ))
    AND (NOT (v_rules ? 'signup_channels') OR COALESCE(u.signup_channel, 'unknown') IN (
      SELECT jsonb_array_elements_text(v_rules->'signup_channels')
    ))
    AND (NOT (v_rules ? 'utm_sources') OR COALESCE(u.signup_utm_source, '') IN (
      SELECT jsonb_array_elements_text(v_rules->'utm_sources')
    ))
    AND (NOT (v_rules ? 'utm_campaigns') OR COALESCE(u.signup_utm_campaign, '') IN (
      SELECT jsonb_array_elements_text(v_rules->'utm_campaigns')
    ))
    AND (NOT (v_rules ? 'landing_pages') OR COALESCE(u.signup_landing_page, '') IN (
      SELECT jsonb_array_elements_text(v_rules->'landing_pages')
    ))
    AND (NOT (v_rules ? 'onboarding_completed') OR u.onboarding_completed = (v_rules->>'onboarding_completed')::boolean)
    AND (NOT (v_rules ? 'has_completed_test') OR (c.user_id IS NOT NULL) = (v_rules->>'has_completed_test')::boolean)
    AND (NOT (v_rules ? 'created_days_max') OR u.created_at >= now() - make_interval(days => (v_rules->>'created_days_max')::integer))
    AND (NOT (v_rules ? 'inactive_days_min') OR COALESCE(u.last_active, u.created_at) <= now() - make_interval(days => (v_rules->>'inactive_days_min')::integer))
    AND (NOT (v_rules ? 'inactive_days_max') OR COALESCE(u.last_active, u.created_at) >= now() - make_interval(days => (v_rules->>'inactive_days_max')::integer))
    AND (NOT (v_rules ? 'payment_failed') OR (u.payment_failed_at IS NOT NULL) = (v_rules->>'payment_failed')::boolean)
    AND (NOT (v_rules ? 'cancel_at_period_end') OR COALESCE(u.cancel_at_period_end, false) = (v_rules->>'cancel_at_period_end')::boolean)
    AND (NOT (v_rules ? 'referral_expiry_days_max') OR u.referral_bonus_expires_at BETWEEN now() AND now() + make_interval(days => (v_rules->>'referral_expiry_days_max')::integer))
    AND (NOT (v_rules ? 'test_date_days_max') OR u.test_date BETWEEN current_date AND current_date + (v_rules->>'test_date_days_max')::integer)
    AND (NOT (v_rules ? 'target_band_min') OR u.target_band_score >= (v_rules->>'target_band_min')::numeric)
    AND (NOT (v_rules ? 'target_band_max') OR u.target_band_score <= (v_rules->>'target_band_max')::numeric)
    AND (NOT (v_rules ? 'weak_modules') OR COALESCE(u.weak_area, '') IN (
      SELECT jsonb_array_elements_text(v_rules->'weak_modules')
    ))
    AND (NOT (v_rules ? 'quota_states') OR
      CASE
        WHEN q.allowed <= q.used THEN 'exhausted'
        WHEN q.allowed - q.used <= 1 THEN 'low'
        ELSE 'available'
      END IN (SELECT jsonb_array_elements_text(v_rules->'quota_states'))
    )
    AND (NOT (v_rules ? 'exclude_active_promo') OR u.promo_discount IS NULL)
    AND (NOT (v_rules ? 'checkout_abandoned_hours_min') OR (
      lc.started_at IS NOT NULL
      AND lc.started_at <= now() - make_interval(hours => (v_rules->>'checkout_abandoned_hours_min')::integer)
      AND NOT EXISTS (
        SELECT 1 FROM public.marketing_events purchase_event
        WHERE purchase_event.user_id = u.id
          AND purchase_event.event_type = 'purchased'
          AND purchase_event.occurred_at > lc.started_at
      )
    ))
    AND (NOT (v_rules ? 'exclude_user_ids') OR NOT (u.id::text = ANY (
      ARRAY(SELECT jsonb_array_elements_text(v_rules->'exclude_user_ids'))
    )))
  ORDER BY u.created_at DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 1000), 1), 10000);
END;
$function$;

-- 4. Token-authenticated unsubscribe ----------------------------------------
--
-- Authenticated by the delivery's own tracking_token, so it works straight from
-- the email with no login — which is the only way an unsubscribe link is
-- actually usable. Idempotent: clicking twice is not an error, and the opt-out
-- timestamp is not overwritten on a repeat click.

CREATE OR REPLACE FUNCTION public.unsubscribe_marketing_email(
  p_delivery_id uuid,
  p_token uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_delivery record;
  v_already boolean;
BEGIN
  SELECT d.id, d.campaign_id, d.user_id
    INTO v_delivery
  FROM public.marketing_deliveries d
  WHERE d.id = p_delivery_id AND d.tracking_token = p_token;

  IF v_delivery.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'invalid_token');
  END IF;

  SELECT marketing_email_unsubscribed_at IS NOT NULL INTO v_already
  FROM public.users WHERE id = v_delivery.user_id;

  UPDATE public.users
  SET marketing_email_unsubscribed_at = COALESCE(marketing_email_unsubscribed_at, now())
  WHERE id = v_delivery.user_id;

  INSERT INTO public.marketing_events (
    campaign_id, delivery_id, user_id, event_type, channel, dedupe_key, metadata
  ) VALUES (
    v_delivery.campaign_id, v_delivery.id, v_delivery.user_id,
    'unsubscribed', 'email',
    v_delivery.id || ':unsubscribed',
    jsonb_build_object('source', 'email_footer_link')
  )
  ON CONFLICT DO NOTHING;

  RETURN jsonb_build_object('ok', true, 'already', COALESCE(v_already, false));
END;
$function$;

REVOKE ALL ON FUNCTION public.unsubscribe_marketing_email(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.unsubscribe_marketing_email(uuid, uuid) TO service_role;

-- 5. Logged-in self-service toggle ------------------------------------------

CREATE OR REPLACE FUNCTION public.set_my_marketing_email_subscription(p_subscribed boolean)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid;
BEGIN
  v_user_id := public.get_my_public_user_id();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '42501';
  END IF;

  UPDATE public.users
  SET marketing_email_unsubscribed_at = CASE WHEN p_subscribed THEN NULL ELSE now() END
  WHERE id = v_user_id;

  RETURN p_subscribed;
END;
$function$;

REVOKE ALL ON FUNCTION public.set_my_marketing_email_subscription(boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.set_my_marketing_email_subscription(boolean) TO authenticated;

-- ============================================================================
-- Source migration: 20260809175250_admin_analytics_revenue_intelligence
-- Source ledger: repository
-- ============================================================================
-- Decision-oriented admin analytics. This intentionally keeps monetary values
-- separated by settlement currency; neither client nor database converts BDT
-- to USD without a dated FX source.

CREATE OR REPLACE FUNCTION public.get_admin_analytics_intelligence(p_range text DEFAULT '30d')
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $function$
DECLARE
    v_days integer;
    v_since timestamptz;
    v_total_users bigint; v_new_users bigint; v_active_users bigint;
    v_testers bigint; v_completed bigint; v_paying bigint;
    v_onboarded bigint; v_started bigint; v_new_user_paid bigint;
    v_trend jsonb; v_recent jsonb;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'Access denied'; END IF;

    v_days := CASE lower(coalesce(p_range, '30d'))
        WHEN '90d' THEN 90 WHEN '1y' THEN 365 ELSE 30 END;
    v_since := (date_trunc('day', now() AT TIME ZONE 'Asia/Dhaka')
        - make_interval(days => v_days - 1)) AT TIME ZONE 'Asia/Dhaka';

    SELECT count(*),
           count(*) FILTER (WHERE created_at >= v_since),
           count(*) FILTER (WHERE last_active >= v_since),
           count(*) FILTER (WHERE subscription_tier IN ('pro', 'premium'))
    INTO v_total_users, v_new_users, v_active_users, v_paying
    FROM public.users;

    SELECT count(DISTINCT ts.user_id), count(*) FILTER (WHERE ts.is_completed)
    INTO v_testers, v_completed
    FROM public.test_sessions ts
    WHERE ts.created_at >= v_since;

    -- This follows people who signed up in the selected period. Each step
    -- describes their current observed state, not a fabricated event timeline.
    SELECT count(*) FILTER (WHERE u.onboarding_completed),
           count(*) FILTER (WHERE EXISTS (
               SELECT 1 FROM public.test_sessions ts WHERE ts.user_id = u.id
           )),
           count(*) FILTER (WHERE u.subscription_tier IN ('pro', 'premium'))
    INTO v_onboarded, v_started, v_new_user_paid
    FROM public.users u
    WHERE u.created_at >= v_since;

    WITH spine AS (
        SELECT generate_series((v_since AT TIME ZONE 'Asia/Dhaka')::date,
                               (now() AT TIME ZONE 'Asia/Dhaka')::date,
                               interval '1 day')::date AS day
    ), signups AS (
        SELECT (created_at AT TIME ZONE 'Asia/Dhaka')::date AS day, count(*) AS n
        FROM public.users WHERE created_at >= v_since GROUP BY 1
    ), practice AS (
        SELECT (created_at AT TIME ZONE 'Asia/Dhaka')::date AS day,
               count(DISTINCT user_id) AS users,
               count(*) FILTER (WHERE is_completed) AS completions
        FROM public.test_sessions WHERE created_at >= v_since GROUP BY 1
    )
    SELECT jsonb_agg(jsonb_build_object(
        'date', to_char(spine.day, CASE WHEN v_days = 365 THEN 'Mon YY' ELSE 'Mon DD' END),
        'signups', coalesce(signups.n, 0), 'testers', coalesce(practice.users, 0),
        'completions', coalesce(practice.completions, 0)
    ) ORDER BY spine.day) INTO v_trend
    FROM spine LEFT JOIN signups USING (day) LEFT JOIN practice USING (day);

    SELECT jsonb_agg(row_to_json(t)::jsonb ORDER BY t.created_at DESC) INTO v_recent
    FROM (
        SELECT id, full_name, email, created_at, subscription_tier, onboarding_completed
        FROM public.users ORDER BY created_at DESC LIMIT 8
    ) t;

    RETURN jsonb_build_object(
        'windowDays', v_days,
        'totalUsers', v_total_users, 'newUsers', v_new_users,
        'activeUsers', v_active_users, 'testers', v_testers,
        'completedTests', v_completed, 'payingUsers', v_paying,
        'conversionRate', CASE WHEN v_total_users > 0 THEN round(100.0 * v_paying / v_total_users, 1) ELSE 0 END,
        'activationRate', CASE WHEN v_new_users > 0 THEN round(100.0 * v_onboarded / v_new_users, 1) ELSE 0 END,
        'funnel', jsonb_build_array(
            jsonb_build_object('label', 'Signed up', 'users', v_new_users),
            jsonb_build_object('label', 'Finished onboarding', 'users', v_onboarded),
            jsonb_build_object('label', 'Started practice', 'users', v_started),
            jsonb_build_object('label', 'Paid', 'users', v_new_user_paid)
        ),
        'trend', coalesce(v_trend, '[]'::jsonb),
        'recentSignups', coalesce(v_recent, '[]'::jsonb)
    );
END;
$function$;

