-- CREATE OR REPLACE preserves old ACLs. Several functions still carried broad
-- grants from the original remote schema even though later migrations intended
-- narrower access. Revoke every inherited/explicit route before regranting the
-- minimum required roles.
REVOKE ALL ON FUNCTION public.current_subscription_tier() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.current_subscription_tier() TO authenticated, service_role;
ALTER FUNCTION public.current_subscription_tier() SET search_path TO '';

REVOKE ALL ON FUNCTION public.get_current_profile_id() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_current_profile_id() TO authenticated, service_role;

REVOKE ALL ON FUNCTION public.get_my_public_user_id() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_my_public_user_id() TO authenticated, service_role;

REVOKE ALL ON FUNCTION public.get_my_user_id() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_my_user_id() TO authenticated, service_role;

REVOKE ALL ON FUNCTION public.is_vocab_owner(uuid, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_vocab_owner(uuid, uuid) TO authenticated, service_role;

-- The email link calls the rate-limited Edge Function, which validates the
-- token and invokes this function with service_role. Direct REST access was not
-- intended and bypassed that boundary.
REVOKE ALL ON FUNCTION public.unsubscribe_marketing_email(uuid, uuid)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.unsubscribe_marketing_email(uuid, uuid)
  TO service_role;

-- Trigger-only/retired helpers must not be exposed as authenticated RPCs.
REVOKE ALL ON FUNCTION public.seed_skills_from_onboarding()
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.seed_skills_from_onboarding() TO service_role;

REVOKE ALL ON FUNCTION public.get_session_counts(uuid[])
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.get_session_counts(uuid[]) TO service_role;

REVOKE ALL ON FUNCTION public.redeem_subscription_promo(text)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.redeem_subscription_promo(text) TO service_role;

-- This function only reads the caller's JWT. Definer privileges are unnecessary
-- and would turn a harmless helper into an RLS-bypassing endpoint.
ALTER FUNCTION public.current_admin_authentication_methods() SECURITY INVOKER;

-- The previous function trusted caller-supplied p_user_id and allowed a caller
-- with a known session UUID to retrieve another learner's complete test_sessions
-- row. Authorize both lookup modes against the authenticated profile (or an
-- explicitly privileged admin/service caller) before returning any session.
CREATE OR REPLACE FUNCTION public.get_writing_session_with_task(
  p_session_id uuid DEFAULT NULL,
  p_task_id text DEFAULT NULL,
  p_user_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  v_session public.test_sessions%ROWTYPE;
  v_task public.passages%ROWTYPE;
  v_effective_task_id text;
BEGIN
  IF p_user_id IS NOT NULL AND NOT public.can_access_user_id(p_user_id) THEN
    RAISE EXCEPTION 'Access denied' USING ERRCODE = '42501';
  END IF;

  IF p_session_id IS NOT NULL THEN
    SELECT session_row.*
      INTO v_session
    FROM public.test_sessions AS session_row
    WHERE session_row.id = p_session_id
      AND (p_user_id IS NULL OR session_row.user_id = p_user_id)
      AND public.can_access_user_id(session_row.user_id)
    LIMIT 1;

    IF FOUND THEN
      v_effective_task_id := coalesce(
        v_session.passage_id::text,
        v_session.content_data->>'id',
        v_session.content_data->>'passage_id',
        p_task_id
      );
    END IF;
  ELSE
    v_effective_task_id := p_task_id;
  END IF;

  IF v_effective_task_id IS NULL THEN
    RETURN jsonb_build_object(
      'error', 'No task ID provided or found in session',
      'session', NULL,
      'task', NULL
    );
  END IF;

  SELECT passage_row.*
    INTO v_task
  FROM public.passages AS passage_row
  WHERE passage_row.id = v_effective_task_id::uuid
    AND passage_row.is_active = true
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'error', 'Task not found or inactive',
      'session', CASE WHEN v_session.id IS NOT NULL THEN to_jsonb(v_session) ELSE NULL END,
      'task', NULL
    );
  END IF;

  IF v_session.id IS NULL AND p_user_id IS NOT NULL AND p_session_id IS NULL THEN
    SELECT session_row.*
      INTO v_session
    FROM public.test_sessions AS session_row
    WHERE session_row.user_id = p_user_id
      AND session_row.test_type = 'writing'
      AND (
        session_row.passage_id::text = v_effective_task_id
        OR session_row.content_data->>'id' = v_effective_task_id
      )
    ORDER BY session_row.created_at DESC
    LIMIT 1;
  END IF;

  RETURN jsonb_build_object(
    'error', NULL,
    'session', CASE WHEN v_session.id IS NOT NULL THEN to_jsonb(v_session) ELSE NULL END,
    'task', to_jsonb(v_task)
  );
END;
$$;

REVOKE ALL ON FUNCTION public.get_writing_session_with_task(uuid, text, uuid)
  FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_writing_session_with_task(uuid, text, uuid)
  TO authenticated, service_role;

