-- policy. Existing authenticated admin write policies remain unchanged.
DROP POLICY IF EXISTS resources_admin_read ON public.resources;
DROP POLICY IF EXISTS resources_public_read ON public.resources;

CREATE POLICY resources_public_read
  ON public.resources
  FOR SELECT
  TO anon
  USING (
    is_published = true
    AND (published_at IS NULL OR published_at <= now())
  );

CREATE POLICY resources_authenticated_read
  ON public.resources
  FOR SELECT
  TO authenticated
  USING (
    (SELECT public.is_admin())
    OR (
      is_published = true
      AND (published_at IS NULL OR published_at <= now())
    )
  );

